import { useEffect, useRef, useState } from 'react'
import { api, bootstrapSession, upload, uploadMany, uploadWithFields, type ApiRecord } from './api/client'
import './App.css'

const nav = [
  ['dashboard', 'Dashboard', '⌂'], ['contacts', 'Contacts', '◎'], ['segments', 'Segments', '◇'], ['data-connections', 'Data Connections', '⇄'], ['integrations', 'Integration Hub', '◌'], ['data-studio', 'Data Studio', '◆'], ['functions', 'Functions', 'ƒ'], ['email-standards', 'Email Standards', '✓'], ['message-studio', 'Message Studio', '✎'], ['campaigns', 'Campaigns', '↗'], ['automations', 'Automations', '✦'], ['list-tools', 'List Tools', '▦'],
  ['inbound', 'Inbound', '↘'], ['providers', 'Providers', '◈'], ['reports', 'Reports & Insights', '▥'], ['activity', 'Activity', '≡'], ['maintenance', 'Maintenance', '⚙'],
]

const navigationGroups = [
  { label: 'Overview', items: ['dashboard', 'activity'] },
  { label: 'Data', items: ['list-tools', 'data-studio', 'data-connections'] },
  { label: 'Audiences', items: ['contacts', 'segments'] },
  { label: 'Communication', items: ['message-studio', 'campaigns'] },
  { label: 'Incoming', items: ['inbound'] },
  { label: 'Automation', items: ['automations', 'functions'] },
  { label: 'Connectivity', items: ['providers', 'integrations'] },
  { label: 'Insights', items: ['reports', 'email-standards'] },
  { label: 'Application', items: ['maintenance'] },
]

const pageMeta: Record<string, { label: string, group: string, description: string }> = {
  dashboard: { label: 'Dashboard', group: 'Overview', description: 'A durable view of local work and attention needed next.' },
  'list-tools': { label: 'List Tools', group: 'Data', description: 'Process local source files without creating contacts or contacting providers.' },
  'data-studio': { label: 'Data Studio', group: 'Data', description: 'Inspect, transform, and hand off durable local data artifacts.' },
  'data-connections': { label: 'Data Connections', group: 'Data', description: 'Acquire bounded read-only snapshots from configured sources.' },
  contacts: { label: 'Contacts', group: 'Audiences', description: 'Import and organize recipient records with source provenance.' },
  segments: { label: 'Segments', group: 'Audiences', description: 'Build revisioned audiences using local, typed rules.' },
  'message-studio': { label: 'Message Studio', group: 'Communication', description: 'Compose, preview, and publish structured message revisions.' },
  campaigns: { label: 'Campaigns', group: 'Communication', description: 'Prepare and simulate policy-aware campaign operations.' },
  inbound: { label: 'Inbound', group: 'Incoming', description: 'Acquire, classify, and review inbound evidence safely.' },
  automations: { label: 'Automations', group: 'Automation', description: 'Define bounded workflows and inspect their durable runs.' },
  functions: { label: 'Functions', group: 'Automation', description: 'Create reusable declarative transformations with pinned revisions.' },
  providers: { label: 'Providers', group: 'Connectivity', description: 'Configure accounts and inspect local protocol evidence.' },
  integrations: { label: 'Integration Hub', group: 'Connectivity', description: 'Manage scoped clients, typed events, and webhook evidence.' },
  reports: { label: 'Reports & Insights', group: 'Insights', description: 'Explore bounded operational observations from local records.' },
  'email-standards': { label: 'Email Standards', group: 'Insights', description: 'Check message and sender evidence before consequential work.' },
  activity: { label: 'Activity', group: 'Overview', description: 'Inspect the append-only operational ledger.' },
  maintenance: { label: 'Runtime & Maintenance', group: 'Application', description: 'Check runtime health and protect local state with backups.' },
}

const relatedViews: Record<string, string[]> = {
  dashboard: ['contacts', 'message-studio', 'campaigns', 'reports'],
  'list-tools': ['data-studio', 'contacts', 'reports'],
  'data-connections': ['data-studio', 'reports'],
  'data-studio': ['contacts', 'message-studio', 'campaigns'],
  contacts: ['segments', 'message-studio', 'campaigns'],
  segments: ['contacts', 'campaigns', 'message-studio'],
  'message-studio': ['campaigns', 'automations', 'contacts'],
  campaigns: ['contacts', 'message-studio', 'providers', 'reports'],
  inbound: ['automations', 'message-studio', 'reports'],
  automations: ['inbound', 'data-studio', 'campaigns', 'reports'],
  functions: ['data-studio', 'message-studio'],
  providers: ['campaigns', 'inbound', 'reports'],
  integrations: ['data-connections', 'automations', 'reports'],
  reports: ['campaigns', 'providers', 'activity'],
  'email-standards': ['message-studio', 'campaigns', 'reports'],
  activity: ['reports', 'maintenance'],
  maintenance: ['activity', 'reports'],
}

function viewFromPath(pathname: string) {
  const segment = pathname.replace(/^\/+/, '').split('/')[0]
  return pageMeta[segment] ? segment : 'dashboard'
}

function App() {
  const [view, setView] = useState(() => viewFromPath(window.location.pathname))
  const [data, setData] = useState<ApiRecord>({})
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState('')
  const [setup, setSetup] = useState<ApiRecord>({})
  const [sessionReady, setSessionReady] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)
  const [mobileViewport, setMobileViewport] = useState(() => window.matchMedia('(max-width: 850px)').matches)
  const [retry, setRetry] = useState<(() => void) | null>(null)
  const mobileMenuRef = useRef<HTMLButtonElement>(null)
  const mobileNavRef = useRef<HTMLElement>(null)
  const loadSequence = useRef(0)

  useEffect(() => {
    const media = window.matchMedia('(max-width: 850px)')
    const update = () => setMobileViewport(media.matches)
    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  const load = async (target = view) => {
    const sequence = ++loadSequence.current
    setBusy(true); setError('')
    try {
      const next = await api(target === 'dashboard' ? '/dashboard' : target === 'list-tools' ? '/list-tools/jobs' : target === 'message-studio' ? '/message-studio/documents' : target === 'data-studio' ? '/data-studio/recipes' : target === 'reports' ? '/reports/summary' : target === 'maintenance' ? '/runtime' : target === 'email-standards' ? '/email-standards' : `/${target}`)
      if (sequence === loadSequence.current) { setData(next); setRetry(null) }
    }
    catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to load this view')
      setRetry(() => () => { void load(target) })
    }
    finally { setBusy(false) }
  }
  const closeMobileNav = () => {
    setMobileNavOpen(false)
    mobileMenuRef.current?.focus()
  }
  const navigate = (target: string, replace = false) => {
    const nextPath = target === 'dashboard' ? '/' : `/${target}`
    if (window.location.pathname !== nextPath) window.history[replace ? 'replaceState' : 'pushState']({}, '', nextPath)
    setView(target)
    if (mobileNavOpen) closeMobileNav()
    void load(target)
  }
  useEffect(() => {
    const onPopState = () => {
      const next = viewFromPath(window.location.pathname)
      setView(next)
      void load(next)
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])
  useEffect(() => {
    if (!mobileNavOpen) return
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setMobileNavOpen(false)
        mobileMenuRef.current?.focus()
        return
      }
      if (event.key === 'Tab') {
        const focusable = Array.from(mobileNavRef.current?.querySelectorAll<HTMLElement>(
          'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled])'
        ) || [])
        if (!focusable.length) return
        const first = focusable[0]
        const last = focusable[focusable.length - 1]
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault()
          last.focus()
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault()
          first.focus()
        }
      }
    }
    document.addEventListener('keydown', onKeyDown)
    requestAnimationFrame(() => mobileNavRef.current?.querySelector<HTMLButtonElement>('.nav-item')?.focus())
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
    }
  }, [mobileNavOpen])
  useEffect(() => { bootstrapSession().then(async () => { setSessionReady(true); setSetup(await api('/setup')); await load(view) }).catch((err) => { setError(err.message); setRetry(() => () => { window.location.reload() }) }) }, [])
  const run = async (action: () => Promise<unknown>, message: string) => {
    setBusy(true); setError('')
    setRetry(null)
    try { await action(); setNotice(message); await load(view) }
    catch (err) { setError(err instanceof Error ? err.message : 'Action failed') }
    finally { setBusy(false) }
  }
  const metadata = pageMeta[view] || pageMeta.dashboard

  return <div className="shell">
    <aside ref={mobileNavRef} id="mailforge-navigation" className={`rail ${mobileNavOpen ? 'mobile-open' : ''}`} aria-hidden={mobileViewport && !mobileNavOpen} inert={mobileViewport && !mobileNavOpen ? true : undefined} tabIndex={mobileViewport && !mobileNavOpen ? -1 : undefined} aria-label="Mailforge navigation"><div className="brand"><button className="brand-button" tabIndex={mobileViewport && !mobileNavOpen ? -1 : undefined} onClick={() => navigate('dashboard')}><span className="brand-mark">M</span><span>Mailforge</span></button></div><p className="eyebrow">LOCAL OPERATIONS</p>
      {navigationGroups.map(group => <div className="nav-group" key={group.label}><p className="nav-group-label">{group.label}</p><nav aria-label={`${group.label} navigation`}>{group.items.map(id => { const navItem = nav.find(([itemId]) => itemId === id); if (!navItem) return null; const [, label, icon] = navItem; return <button key={id} tabIndex={mobileViewport && !mobileNavOpen ? -1 : undefined} className={view === id ? 'nav-item active' : 'nav-item'} onClick={() => navigate(id)}><span aria-hidden="true">{icon}</span><span className="nav-label">{label}</span>{id === 'activity' && <span className="nav-dot" />}</button> })}</nav></div>)}
      <div className="rail-foot"><span className="live-dot" /> Loopback only<br /><small>Simulation mode · no external delivery</small></div>
    </aside>
    <main className="main"><header className="topbar"><div className="topbar-heading"><button ref={mobileMenuRef} className="mobile-menu-button" aria-label={mobileNavOpen ? 'Close navigation' : 'Open navigation'} aria-expanded={mobileNavOpen} aria-controls="mailforge-navigation" onClick={() => setMobileNavOpen(open => !open)}>☰</button><div><p className="eyebrow">{metadata.group.toUpperCase()} / LOCAL WORKSPACE</p><h1>{metadata.label}</h1><p className="page-description">{metadata.description}</p></div></div><div className="top-actions"><span className="status-chip"><span className="live-dot" /> Local</span><button className="icon-button" aria-label="Refresh" onClick={() => void load()}>↻</button></div></header>
      {mobileNavOpen && <button className="nav-scrim" aria-label="Close navigation" onClick={closeMobileNav} />}
      {notice && <div className="notice" role="status">{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notification">×</button></div>}{error && <div className="error" role="alert"><span>{error}</span>{retry && <button onClick={retry}>Retry</button>}<button onClick={() => setError('')} aria-label="Dismiss error">×</button></div>}{busy && <div className="loading" aria-live="polite">Updating local state…</div>}
      <RelatedWork view={view} onNavigate={navigate} />
      {view === 'dashboard' && <Dashboard data={data} setup={setup} onSetup={async () => { await api('/setup/complete', { method: 'POST', body: JSON.stringify({ timezone: 'UTC', simulation_mode: true, sample_data: false }) }); setSetup({ ...setup, complete: true }); setNotice('Setup saved; Mailforge is ready for local work') }} onNavigate={navigate} />}{view === 'contacts' && <Contacts data={data} onRun={run} />}{view === 'segments' && <Segments data={data} onRun={run} />}{view === 'data-connections' && <DataConnections onRun={run} />}{view === 'integrations' && <IntegrationHub data={data} onRun={run} onNavigate={navigate} />}{view === 'data-studio' && <DataStudio data={data} onRun={run} />}{view === 'functions' && <Functions data={data} onRun={run} />}{view === 'email-standards' && <EmailStandards data={data} onRun={run} />}{view === 'message-studio' && <MessageStudio data={data} onRun={run} />}{view === 'campaigns' && <Campaigns data={data} onRun={run} />}{view === 'automations' && <Automations data={data} onRun={run} />}{view === 'list-tools' && <ListTools data={data} onRun={run} />}{view === 'inbound' && <Inbound data={data} onRun={run} />}{view === 'providers' && <Providers data={data} onRun={run} sessionReady={sessionReady} />}{view === 'reports' && <Reports data={data} onNavigate={navigate} />}{view === 'activity' && <Activity data={data} />}{view === 'maintenance' && <Maintenance data={data} onRun={run} />}
    </main>
  </div>
}

function RelatedWork({ view, onNavigate }: { view: string, onNavigate: (view: string) => void }) {
  const links = relatedViews[view] || []
  if (!links.length) return null
  return <section className="related-work" aria-label="Related work"><span className="related-label">Continue with</span>{links.map(id => <a key={id} href={id === 'dashboard' ? '/' : `/${id}`} onClick={event => { event.preventDefault(); onNavigate(id) }}>{pageMeta[id].label} <span aria-hidden="true">→</span></a>)}</section>
}

function Dashboard({ data, setup, onSetup, onNavigate }: { data: ApiRecord, setup: ApiRecord, onSetup: () => Promise<void>, onNavigate: (view: string) => void }) { const counts = data.counts || {}; return <div className="content">{!setup.complete && <section className="panel onboarding" aria-labelledby="welcome-heading"><p className="eyebrow teal">FIRST RUN</p><h3 id="welcome-heading">Set up your local workspace</h3><p className="muted">Mailforge keeps campaigns, contacts, assets, and processing history in a local data directory. It starts in simulation mode; no provider is contacted and no message is sent.</p><div className="button-row"><button className="primary" onClick={() => void onSetup()}>Finish local setup</button><button onClick={() => onNavigate('maintenance')}>Review runtime details</button></div></section>}<div className="hero-copy"><div><p className="eyebrow teal">OPERATOR OVERVIEW</p><h2>Make every send<br /><em>accountable.</em></h2><p className="lede">A calm, local control room for contacts, policy-aware campaigns, and inbound signals.</p></div><div className="hero-note"><span className="stamp">LOCAL<br />FIRST</span><p>Durable actions<br />stay in your SQLite<br />authority.</p></div></div><div className="stat-grid"><Stat label="Contacts" value={counts.contacts ?? 0} tone="teal" /><Stat label="Lists" value={counts.lists ?? 0} /><Stat label="Inbound reviews" value={counts.inbound?.pending_reviews ?? 0} tone="amber" /><Stat label="Schema" value={`v${data.schema_version ?? data.supported_schema_version ?? 'unknown'}`} /></div><section className="section-head"><div><p className="eyebrow">RECENT WORK</p><h3>Campaign pulse</h3></div><button className="text-button" onClick={() => onNavigate('campaigns')}>View campaigns ↗</button></section><CampaignTable items={data.campaigns || []} empty="No campaigns yet. Create a list and launch a synthetic campaign to begin." /></div> }

function Functions({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [name, setName] = useState('normalize_company_label')
  const [operation, setOperation] = useState('text.whitespace')
  const [field, setField] = useState('company')
  const [output, setOutput] = useState('company_normalized')
  const [selected, setSelected] = useState<ApiRecord | null>(null)
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const [revisions, setRevisions] = useState<ApiRecord[]>([])
  const items: ApiRecord[] = data.items || []
  const create = () => onRun(() => api('/functions', { method: 'POST', body: JSON.stringify({ name, definition: { operation, contexts: ['data_studio', 'message_studio'], input_schema: { type: 'object' }, output_schema: { type: 'object' }, parameters: { field, output_field: output } } }) }), 'Declarative function revision saved')
  const toggle = (item: ApiRecord) => onRun(() => api(`/functions/${item.name}/${item.enabled ? 'disable' : 'enable'}`, { method: 'POST' }), `${item.name} ${item.enabled ? 'disabled' : 'enabled'}`)
  const inspect = async (item: ApiRecord) => { setSelected(item); setPreview(null); const result = await api<ApiRecord>(`/functions/${item.name}/revisions`); setRevisions(result.items || []) }
  const runPreview = () => selected && onRun(async () => { const revision = revisions[0]; const result = await api<ApiRecord>(`/functions/${selected.name}/preview`, { method: 'POST', body: JSON.stringify({ revision_id: revision?.id, records: [{ [field]: `  sample ${selected.name}  ` }] }) }); setPreview(result); return result }, 'Function preview completed')
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">FUNCTION WORKBENCH</p><h2>Reusable, pinned transformations.</h2><p className="muted">Declarative functions are enabled immediately. Trusted Python remains a separate local-only registration path and is disabled until explicitly enabled.</p></div><span className="status-chip">{items.length} registered</span></div><div className="split"><section className="panel"><h3>Create a declarative function</h3><label>Name<input aria-label="Function name" value={name} onChange={event => setName(event.target.value)} /></label><label>Operation<select aria-label="Function operation" value={operation} onChange={event => setOperation(event.target.value)}><option value="text.trim">Trim text</option><option value="text.whitespace">Normalize whitespace</option><option value="text.lower">Lowercase</option><option value="text.upper">Uppercase</option><option value="email.normalize">Normalize email</option><option value="email.domain">Extract email domain</option></select></label><label>Input field<input value={field} onChange={event => setField(event.target.value)} /></label><label>Output field<input value={output} onChange={event => setOutput(event.target.value)} /></label><button className="primary full" disabled={!name || !field || !output} onClick={create}>Save revision</button></section><section className="panel table-panel"><div className="panel-head"><div><h3>Registry</h3><p className="muted">Every consumer pins a revision and content hash; executable source is never accepted here.</p></div></div>{items.length ? items.map(item => <div className="list-row" key={item.id}><button className="text-button" onClick={() => void inspect(item)}><strong>{item.name}</strong><small>{item.kind} · v{item.version} · {item.enabled ? 'enabled' : 'disabled'} · {item.trusted ? 'trusted local' : 'declarative'}</small></button>{item.kind === 'python' && <button onClick={() => toggle(item)}>{item.enabled ? 'Disable' : 'Enable'}</button>}</div>) : <Empty text="No functions yet. Create a bounded declarative transformation to begin." />}</section></div>{selected && <section className="panel"><div className="panel-head"><div><h3>{selected.name} revisions</h3><p className="muted">Pinned revisions and deterministic previews.</p></div><button onClick={runPreview}>Preview sample</button></div><div className="list-stack">{revisions.map(revision => <div className="list-row" key={revision.id}><span><strong>Revision {revision.revision_number}</strong><small>{revision.content_hash?.slice(0, 16)} · {revision.created_at}</small></span></div>)}</div>{preview && <pre className="preview-json">{JSON.stringify(preview.records || preview, null, 2)}</pre>}</section>}</div>
}

function EmailStandards({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [identityRef, setIdentityRef] = useState('primary-sender')
  const [from, setFrom] = useState('sender@example.com')
  const [envelope, setEnvelope] = useState('bounce@example.com')
  const [domain, setDomain] = useState('example.com')
  const [selector, setSelector] = useState('mail')
  const [diagnostic, setDiagnostic] = useState<ApiRecord | null>(null)
  const [message, setMessage] = useState('From: sender@example.com\nTo: recipient@example.com\nDate: Tue, 28 Oct 2026 12:00:00 +0000\nMessage-ID: <sample@example.com>\nSubject: Standards check\n\nHello')
  const [messageResult, setMessageResult] = useState<ApiRecord | null>(null)
  const [endpointRef, setEndpointRef] = useState('local-unsubscribe')
  const [endpointUrl, setEndpointUrl] = useState('https://unsubscribe.example.invalid/mailforge')
  const [readiness, setReadiness] = useState<ApiRecord | null>(null)
  const identities: ApiRecord[] = data.identities || []
  const saveIdentity = () => onRun(() => api('/email-standards/identities', { method: 'POST', body: JSON.stringify({ identity_ref: identityRef, visible_from: from, envelope_from: envelope, dkim_domain: domain, dkim_selector: selector }) }), 'Sender identity saved')
  const inspectDomain = () => onRun(async () => { const result = await api<ApiRecord>('/email-standards/domains/diagnose', { method: 'POST', body: JSON.stringify({ domain, envelope_from: envelope, dkim_selector: selector, allow_network: false }) }); setDiagnostic(result); return result }, 'Domain diagnostics recorded')
  const validateMessage = () => onRun(async () => { const result = await api<ApiRecord>('/email-standards/messages/validate', { method: 'POST', body: JSON.stringify({ message, communication_purpose: 'marketing', expected_identity: identityRef }) }); setMessageResult(result); return result }, 'Message validation completed')
  const saveEndpoint = () => onRun(() => api('/email-standards/unsubscribe/endpoints', { method: 'POST', body: JSON.stringify({ endpoint_ref: endpointRef, base_url: endpointUrl, verification_status: 'external_configured' }) }), 'Unsubscribe endpoint recorded')
  const checkReadiness = () => onRun(async () => { const result = await api<ApiRecord>('/email-standards/unsubscribe/readiness', { method: 'POST', body: JSON.stringify({ communication_purpose: 'marketing', endpoint_ref: endpointRef, message }) }); setReadiness(result); return result }, 'Unsubscribe readiness evaluated')
  const findings = (value: ApiRecord | null) => value?.findings?.map((finding: ApiRecord) => <div className={`finding ${finding.severity}`} key={`${finding.code}-${finding.message}`}><strong>{finding.code}</strong><span>{finding.message}</span><small>{finding.action || finding.source}</small></div>)
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">EMAIL STANDARDS</p><h2>Find configuration problems before they become sending problems.</h2><p className="muted">Evidence is labelled as configured, observed, claimed, verified, or unknown. Local checks never imply provider acceptance or inbox delivery.</p></div><span className="status-chip">{identities.length} identities</span></div><div className="split"><section className="panel"><h3>Sender identity</h3><p className="muted">Keep visible From, envelope sender, Reply-To, DKIM, and provider identity distinct.</p><label>Identity reference<input value={identityRef} onChange={e => setIdentityRef(e.target.value)} /></label><label>Visible From<input value={from} onChange={e => setFrom(e.target.value)} /></label><label>Envelope MAIL FROM<input value={envelope} onChange={e => setEnvelope(e.target.value)} /></label><label>Sending domain<input value={domain} onChange={e => setDomain(e.target.value)} /></label><label>DKIM selector<input value={selector} onChange={e => setSelector(e.target.value)} /></label><button className="primary full" onClick={saveIdentity}>Save identity</button>{identities.map(identity => <div className="list-row" key={identity.identity_ref}><span><strong>{identity.identity_ref}</strong><small>{identity.visible_from} · DKIM {identity.dkim_selector || 'unknown'}</small></span><span className="tag">configured</span></div>)}</section><section className="panel"><div className="panel-head"><div><h3>Domain diagnostics</h3><p className="muted">Offline mode uses no DNS. Run an explicit inspection when network evidence is authorized.</p></div><button onClick={inspectDomain}>Inspect domain</button></div>{diagnostic ? <><div className="metric-list"><div><dt>SPF</dt><dd>{diagnostic.spf?.status || 'unknown'}</dd></div><div><dt>DMARC</dt><dd>{diagnostic.dmarc?.status || 'unknown'}</dd></div><div><dt>DNS mode</dt><dd>{diagnostic.allow_network ? 'observed' : 'not requested'}</dd></div></div><div className="finding-stack">{findings(diagnostic)}</div></> : <Empty text="No domain observation yet. Inspect a domain to see bounded SPF, DKIM, DMARC, MX, and host evidence." />}</section></div><section className="panel"><div className="panel-head"><div><h3>Message and MIME validation</h3><p className="muted">Uses the same standards boundary as prepared messages; imported Authentication-Results remain untrusted claims.</p></div><button className="primary" onClick={validateMessage}>Validate message</button></div><textarea aria-label="Message source" rows={12} value={message} onChange={e => setMessage(e.target.value)} />{messageResult && <div className="finding-stack">{findings(messageResult)}<p className="muted">Authentication evidence: {messageResult.authentication?.dkim_signatures?.length || 0} DKIM signature claims · {messageResult.authentication?.authentication_results?.length || 0} Authentication-Results headers</p></div>}</section><div className="split"><section className="panel"><div className="panel-head"><div><h3>Unsubscribe readiness</h3><p className="muted">Configure a provider-neutral endpoint, then evaluate marketing readiness. RFC 8058 remains blocked without signed final bytes.</p></div></div><label>Endpoint reference<input aria-label="Unsubscribe endpoint reference" value={endpointRef} onChange={e => setEndpointRef(e.target.value)} /></label><label>Endpoint base URL<input aria-label="Unsubscribe endpoint URL" value={endpointUrl} onChange={e => setEndpointUrl(e.target.value)} /></label><div className="button-row"><button onClick={saveEndpoint}>Save endpoint</button><button className="primary" onClick={checkReadiness}>Check marketing readiness</button></div>{readiness && <div className="finding-stack" role="status"><strong>{readiness.status}</strong>{findings(readiness)}</div>}</section><section className="panel"><div className="panel-head"><div><h3>Diagnostic history</h3><p className="muted">Durable standards observations and their evidence class.</p></div></div>{data.history?.length ? <div className="list-stack">{data.history.slice(0, 8).map((item: ApiRecord) => <div className="list-row" key={item.id}><span><strong>{item.kind} · {item.status}</strong><small>{item.observed_at} · {item.evidence?.evidence_class || 'durable local observation'}</small></span></div>)}</div> : <Empty text="No standards diagnostics recorded yet." />}</section></div><section className="panel"><div className="panel-head"><div><h3>Provider guidance</h3><p className="muted">Versioned reference guidance, not universal legal or provider approval.</p></div></div>{(data.guidance || []).map((item: ApiRecord) => <div className="list-row" key={item.provider}><span><strong>{item.provider}</strong><small>Reviewed {item.reviewed_at} · {item.scope}</small></span><span className="tag">reference</span></div>)}</section></div>
}

function Maintenance({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  type PreferenceKey = 'timezone' | 'simulation_mode' | 'sample_data'
  const [backups, setBackups] = useState<ApiRecord[]>([])
  const [timezone, setTimezone] = useState(String(data.preferences?.timezone || 'UTC'))
  const [simulationMode, setSimulationMode] = useState(data.preferences?.simulation_mode !== false)
  const [sampleData, setSampleData] = useState(Boolean(data.preferences?.sample_data))
  const [selectedBackup, setSelectedBackup] = useState('')
  const [restoreDestination, setRestoreDestination] = useState('qualification-restore')
  const [preferencesLoaded, setPreferencesLoaded] = useState(false)
  const dirtyPreferences = useRef<Set<PreferenceKey>>(new Set())
  const preferenceDraft = useRef({ timezone, simulationMode, sampleData })
  preferenceDraft.current = { timezone, simulationMode, sampleData }
  useEffect(() => {
    if (!data.preferences || Object.keys(data.preferences).length === 0) return
    setPreferencesLoaded(true)
    if (!dirtyPreferences.current.has('timezone')) setTimezone(String(data.preferences.timezone || 'UTC'))
    if (!dirtyPreferences.current.has('simulation_mode')) setSimulationMode(data.preferences.simulation_mode !== false)
    if (!dirtyPreferences.current.has('sample_data')) setSampleData(data.preferences.sample_data === true)
  }, [data.preferences?.timezone, data.preferences?.simulation_mode, data.preferences?.sample_data])
  const refresh = async () => { const result = await api('/runtime/backups'); setBackups(result.items || []) }
  useEffect(() => { void refresh() }, [])
  const savePreferences = () => {
    const submitted = { timezone, simulationMode, sampleData }
    return onRun(async () => {
      await api('/setup/complete', { method: 'POST', body: JSON.stringify({ timezone: submitted.timezone, simulation_mode: submitted.simulationMode, sample_data: submitted.sampleData }) })
      const current = preferenceDraft.current
      if (current.timezone === submitted.timezone) dirtyPreferences.current.delete('timezone')
      if (current.simulationMode === submitted.simulationMode) dirtyPreferences.current.delete('simulation_mode')
      if (current.sampleData === submitted.sampleData) dirtyPreferences.current.delete('sample_data')
    }, 'Application preferences saved')
  }
  const restore = () => selectedBackup && onRun(() => api('/runtime/restore', { method: 'POST', body: JSON.stringify({ backup_name: selectedBackup, destination_name: restoreDestination }) }), 'Backup restored into a staged destination')
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">RUNTIME &amp; MAINTENANCE</p><h2>Keep the local service healthy.</h2><p className="muted">The browser is only the operator interface. The supervised local service owns background work and remains active when this tab closes.</p></div><span className="status-chip"><span className="live-dot" /> {data.running ? 'Running' : 'Stopped'}</span></div><div className="split"><section className="panel"><div className="panel-head"><div><h3>Runtime status</h3><p className="muted">Safe diagnostics only; credential values and full filesystem paths are never displayed.</p></div></div><dl className="metric-list"><div><dt>Application</dt><dd>{data.version || '—'}</dd></div><div><dt>Data directory</dt><dd>{data.data_directory_id || '—'}</dd></div><div><dt>Database schema</dt><dd>{data.schema_version ?? '—'} / {data.supported_schema_version ?? '—'}</dd></div><div><dt>Database integrity</dt><dd>{data.database_integrity === true ? 'verified' : 'not verified'}</dd></div><div><dt>Worker</dt><dd>{data.worker_status?.campaigns_active ?? 0} campaigns · {data.worker_status?.automations_active ?? 0} workflows</dd></div></dl><div className="button-row"><button onClick={() => window.location.reload()}>Reopen interface</button><button onClick={() => void refresh()}>Refresh backups</button></div><p className="muted">To stop or restart the application, use the Mailforge launcher. Closing this browser does not stop the service.</p></section><section className="panel"><div className="panel-head"><div><h3>Application preferences</h3><p className="muted">These are the existing onboarding settings authority; no duplicate Settings store is created.</p></div></div><label>Timezone<input aria-label="Application timezone" value={timezone} disabled={!preferencesLoaded} onChange={event => { dirtyPreferences.current.add('timezone'); setTimezone(event.target.value) }} /></label><label className="check-line"><input type="checkbox" checked={simulationMode} disabled={!preferencesLoaded} onChange={event => { dirtyPreferences.current.add('simulation_mode'); setSimulationMode(event.target.checked) }} /> Keep synthetic simulation mode enabled</label><label className="check-line"><input type="checkbox" checked={sampleData} disabled={!preferencesLoaded} onChange={event => { dirtyPreferences.current.add('sample_data'); setSampleData(event.target.checked) }} /> Allow sample data during onboarding</label><button className="primary full" disabled={!preferencesLoaded} onClick={savePreferences}>Save application preferences</button></section></div><section className="panel"><div className="panel-head"><div><h3>Application backups</h3><p className="muted">Archives include SQLite, settings, and local processing artifacts with a compatibility manifest.</p></div><button className="primary" onClick={() => onRun(async () => { const result = await api('/runtime/backup', { method: 'POST' }); await refresh(); return result }, 'Application backup created')}>Create backup</button></div>{backups.length ? <div className="list-stack">{backups.map((backup: ApiRecord) => { const backupName = backup.path?.split('/').pop() || ''; return <div className={selectedBackup === backupName ? 'list-row selected' : 'list-row'} key={backup.path} onClick={() => backup.valid && setSelectedBackup(backupName)} tabIndex={backup.valid ? 0 : undefined} onKeyDown={event => event.key === 'Enter' && backup.valid && setSelectedBackup(backupName)}><span><strong>{backupName}</strong><small>{backup.valid ? `schema ${backup.schema_version} · ${backup.file_count} files` : `Invalid: ${backup.error}`}</small></span><span className={backup.valid ? 'tag' : 'tag amber-chip'}>{backup.valid ? 'verified' : 'rejected'}</span></div>})}</div> : <p className="muted">No application backup has been created yet.</p>}{selectedBackup && <div className="restore-controls"><label>Staged restore destination<input aria-label="Restore destination" value={restoreDestination} onChange={event => setRestoreDestination(event.target.value)} /></label><button className="primary" onClick={restore}>Restore selected backup</button><p className="muted">Restore creates a new destination and never overwrites the active data directory.</p></div>}</section><section className="panel"><h3>Recovery boundary</h3><p className="muted">Restore is deliberately staged into a new local destination. The active data directory is never overwritten from the browser, and incompatible or tampered archives are refused.</p></section></div>
}

function DataConnections({ onRun }: { onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [profiles, setProfiles] = useState<ApiRecord[]>([])
  const [selected, setSelected] = useState<ApiRecord | null>(null)
  const [schema, setSchema] = useState<ApiRecord>({})
  const [preview, setPreview] = useState<ApiRecord>({})
  const [snapshots, setSnapshots] = useState<ApiRecord[]>([])
  const [name, setName] = useState('Disposable source')
  const [sourceType, setSourceType] = useState('sqlite')
  const [file, setFile] = useState<File | null>(null)
  const [host, setHost] = useState('127.0.0.1')
  const [port, setPort] = useState('5432')
  const [database, setDatabase] = useState('mailforge')
  const [user, setUser] = useState('readonly')
  const [credentialRef, setCredentialRef] = useState('env:MAILFORGE_DATA_PASSWORD')
  const [httpOrigin, setHttpOrigin] = useState('https://api.example.invalid')
  const [httpPath, setHttpPath] = useState('/records')
  const [httpFormat, setHttpFormat] = useState('json')
  const [httpAuthMode, setHttpAuthMode] = useState('public')
  const [table, setTable] = useState('')
  const [worksheet, setWorksheet] = useState('')
  const [recipeRevision, setRecipeRevision] = useState('')
  const [localError, setLocalError] = useState('')

  const loadProfiles = async () => { const result = await api<ApiRecord>('/data-connections'); setProfiles(result.items || []) }
  useEffect(() => { void loadProfiles() }, [])
  const choose = async (profile: ApiRecord) => {
    setSelected(profile); setLocalError(''); setPreview({}); setSchema({})
    try { const [nextSchema, nextSnapshots] = await Promise.all([api<ApiRecord>(`/data-connections/${profile.id}/schema`), api<ApiRecord>(`/data-connections/${profile.id}/snapshots`)]); setSchema(nextSchema); setSnapshots(nextSnapshots.items || []); const object = nextSchema.objects?.[0]; const sheet = nextSchema.worksheets?.[0]; setTable(object?.name || ''); setWorksheet(sheet?.name || '') } catch (err) { setLocalError(err instanceof Error ? err.message : 'Unable to inspect source') }
  }
  const create = () => {
    setLocalError('');
    if ((sourceType === 'sqlite' || sourceType === 'xlsx') && file) return onRun(async () => { const result = await uploadWithFields('/data-connections/sources', file, { profile_name: name, source_type: sourceType }); await loadProfiles(); await choose(result); return result }, 'Data source saved')
    return onRun(async () => { const config = sourceType === 'http' ? { origin: httpOrigin, path: httpPath, format: httpFormat, auth_mode: httpAuthMode, pagination: { mode: 'single', page_size: 100 } } : { host, port: Number(port), database, user, sslmode: 'verify-full' }; const result = await api<ApiRecord>('/data-connections', { method: 'POST', body: JSON.stringify({ name, source_type: sourceType, config, credential_ref: sourceType === 'http' && httpAuthMode === 'public' ? undefined : credentialRef }) }); await loadProfiles(); await choose(result); return result }, sourceType === 'http' ? 'HTTP source saved' : 'PostgreSQL source saved')
  }
  const selection = () => sourceType === 'xlsx' || selected?.source_type === 'xlsx' ? { worksheet, header_row: 1, columns: undefined, formula_policy: 'cached_or_null' } : selected?.source_type === 'http' ? {} : { table: table || undefined }
  const inspect = () => selected && onRun(async () => { const result = await api<ApiRecord>(`/data-connections/${selected.id}/preview`, { method: 'POST', body: JSON.stringify({ selection: selection(), limit: 50 }) }); setPreview(result); return result }, 'Bounded preview loaded')
  const refreshSnapshots = async () => { if (!selected) return; const result = await api<ApiRecord>(`/data-connections/${selected.id}/snapshots`); setSnapshots(result.items || []) }
  const startSnapshot = () => selected && onRun(async () => { const result = await api<ApiRecord>(`/data-connections/${selected.id}/snapshots`, { method: 'POST', body: JSON.stringify({ selection: selection(), wait: false, idempotency_key: `ui-${Date.now()}` }) }); setSnapshots(items => [result, ...items]); const poll = async () => { const current = await api<ApiRecord>(`/data-connections/snapshots/${result.id}`); setSnapshots(items => items.map(item => item.id === result.id ? current : item)); if (current.status === 'pending' || current.status === 'running') window.setTimeout(() => void poll(), 500); else await refreshSnapshots() }; window.setTimeout(() => void poll(), 250); return result }, 'Snapshot extraction started')
  const handoff = (snapshotId: string) => onRun(() => api(`/data-connections/snapshots/${snapshotId}/data-studio`, { method: 'POST', body: JSON.stringify({ recipe_revision_id: recipeRevision }) }), 'Snapshot handed to Data Studio')
  const objects = schema.objects || schema.worksheets || []
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">DATA CONNECTIONS</p><h2>Bring in durable source snapshots.</h2><p className="muted">Read-only SQLite, PostgreSQL, XLSX, and fixed-origin HTTP sources. Preview first; consequential work uses a frozen local snapshot.</p></div><span className="status-chip">{profiles.length} sources</span></div>
    <div className="split"><section className="panel"><div className="panel-head"><div><h3>Add a source</h3><p className="muted">Passwords stay outside Mailforge. HTTP uses fixed-origin GET with bounded JSON, JSONL, or CSV responses.</p></div></div><label>Source name<input aria-label="Data source name" value={name} onChange={event => setName(event.target.value)} /></label><label>Source type<select aria-label="Data source type" value={sourceType} onChange={event => setSourceType(event.target.value)}><option value="sqlite">External SQLite</option><option value="postgresql">PostgreSQL</option><option value="xlsx">Excel workbook (.xlsx)</option><option value="http">HTTP / REST (read-only)</option></select></label>{sourceType === 'postgresql' ? <><label>Host<input value={host} onChange={event => setHost(event.target.value)} /></label><label>Port<input type="number" value={port} onChange={event => setPort(event.target.value)} /></label><label>Database<input value={database} onChange={event => setDatabase(event.target.value)} /></label><label>Read-only user<input value={user} onChange={event => setUser(event.target.value)} /></label><label>Credential reference<input value={credentialRef} onChange={event => setCredentialRef(event.target.value)} /></label></> : sourceType === 'http' ? <><label>Fixed HTTPS origin<input value={httpOrigin} onChange={event => setHttpOrigin(event.target.value)} placeholder="https://api.example.com" /></label><label>Path<input value={httpPath} onChange={event => setHttpPath(event.target.value)} /></label><label>Response format<select value={httpFormat} onChange={event => setHttpFormat(event.target.value)}><option value="json">JSON</option><option value="jsonl">JSONL</option><option value="csv">CSV</option></select></label><label>Authentication<select value={httpAuthMode} onChange={event => setHttpAuthMode(event.target.value)}><option value="public">Public</option><option value="api_key">API key reference</option><option value="bearer">Bearer reference</option></select></label>{httpAuthMode !== 'public' && <label>Credential reference<input value={credentialRef} onChange={event => setCredentialRef(event.target.value)} /></label>}</> : <label className="file-drop">{file ? file.name : `Choose ${sourceType === 'xlsx' ? 'an XLSX workbook' : 'a SQLite database'}`}<input aria-label="Data source file" type="file" accept={sourceType === 'xlsx' ? '.xlsx' : '.sqlite,.sqlite3,.db'} onChange={event => setFile(event.target.files?.[0] || null)} /></label>}<button className="primary full" disabled={!name || (sourceType === 'postgresql' ? !host || !database || !user || !credentialRef : sourceType === 'http' ? !httpOrigin || !httpPath || (httpAuthMode !== 'public' && !credentialRef) : !file)} onClick={create}>Save source</button></section><section className="panel table-panel"><div className="panel-head"><div><h3>Configured sources</h3><p className="muted">Select a source to inspect schema, preview records, and create a frozen snapshot.</p></div></div>{profiles.length ? profiles.map(profile => <button className={selected?.id === profile.id ? 'list-row selected' : 'list-row'} key={profile.id} onClick={() => void choose(profile)}><span><strong>{profile.name}</strong><small>{profile.source_type} · {profile.enabled ? 'enabled' : 'disabled'} · {profile.last_test_status || 'not tested'}</small></span><b>Inspect →</b></button>) : <Empty text="No data sources yet. Add a disposable SQLite, XLSX, or HTTPS source to begin." />}</section></div>
    {selected && <><section className="panel"><div className="panel-head"><div><h3>{selected.name} schema</h3><p className="muted">Only discovered tables, views, worksheets, and fields can be selected; arbitrary SQL is not available.</p></div><div className="button-row"><button onClick={() => onRun(() => api(`/data-connections/${selected.id}/test`, { method: 'POST' }), 'Connection test completed')}>Test connection</button><button onClick={() => void choose(selected)}>Refresh schema</button><button onClick={() => onRun(() => api(`/data-connections/${selected.id}/disable`, { method: 'POST' }), 'Source disabled')}>Disable</button></div></div><div className="inline-fields">{selected.source_type === 'xlsx' ? <label>Worksheet<select value={worksheet} onChange={event => setWorksheet(event.target.value)}>{objects.map((item: ApiRecord) => <option key={item.name} value={item.name}>{item.name}</option>)}</select></label> : <label>Table or view<select value={table} onChange={event => setTable(event.target.value)}>{objects.map((item: ApiRecord) => <option key={item.name} value={item.name}>{item.name} · {item.kind}</option>)}</select></label>}<button onClick={inspect}>Preview 50 rows</button></div>{objects.length ? <div className="list-stack">{objects.map((item: ApiRecord) => <div className="list-row" key={item.name}><span><strong>{item.name}</strong><small>{item.fields?.map((field: ApiRecord) => `${field.name} · ${field.normalized_type}`).join(' · ')}</small></span><span className="tag">{item.fields?.length || 0} fields</span></div>)}</div> : <Empty text="No accessible tables, views, or worksheets were discovered." />}</section><section className="panel"><div className="panel-head"><div><h3>Bounded preview</h3><p className="muted">Preview rows include source identity and conversion diagnostics where applicable.</p></div></div>{localError && <div className="error" role="alert">{localError}</div>}{preview.rows?.length ? <pre className="preview-json">{JSON.stringify(preview.rows, null, 2)}</pre> : <Empty text="Choose a table or worksheet, then preview records." />}</section><section className="panel"><div className="panel-head"><div><h3>Snapshot history</h3><p className="muted">Each refresh creates a new immutable local artifact. Incomplete extraction is never published as completed.</p></div><button className="primary" onClick={startSnapshot}>Create snapshot</button></div>{snapshots.length ? snapshots.map(snapshot => <div className="list-row" key={snapshot.id}><span><strong>Revision {snapshot.revision} · {snapshot.status}</strong><small>{snapshot.record_count || 0} rows · {snapshot.error_count || 0} conversion issues · {snapshot.artifact_sha256?.slice(0, 12) || 'pending'}</small></span>{snapshot.status === 'completed' && <div className="button-row"><input aria-label="Data Studio recipe revision" placeholder="Recipe revision ID" value={recipeRevision} onChange={event => setRecipeRevision(event.target.value)} /><button disabled={!recipeRevision} onClick={() => handoff(snapshot.id)}>Open in Data Studio</button></div>}</div>) : <Empty text="No snapshots yet." />}</section></>}
  </div>
}
function IntegrationHub({ data, onRun, onNavigate }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void, onNavigate: (view: string) => void }) {
  const clients: ApiRecord[] = data.clients?.items || []
  const subscriptions: ApiRecord[] = data.subscriptions?.items || []
  const events: ApiRecord[] = data.events?.items || []
  const deliveries: ApiRecord[] = data.deliveries?.items || []
  const [clientName, setClientName] = useState('Local workflow client')
  const [clientScope, setClientScope] = useState('INGEST_LOCAL_EVENT')
  const [clientExpiry, setClientExpiry] = useState(() => new Date(Date.now() + 30 * 86400000).toISOString())
  const [issued, setIssued] = useState<ApiRecord | null>(null)
  const [token, setToken] = useState('')
  const [eventId, setEventId] = useState(() => `browser-event-${Date.now()}`)
  const [eventSource, setEventSource] = useState('browser-qualification')
  const [incomingEventType, setIncomingEventType] = useState('approved_local_operation_completed')
  const [eventTime, setEventTime] = useState(() => new Date().toISOString())
  const [eventPayload, setEventPayload] = useState('{"operation":"browser qualification","records":1}')
  const [eventResult, setEventResult] = useState<ApiRecord | null>(null)
  const [webhookName, setWebhookName] = useState('Local operational receiver')
  const [endpoint, setEndpoint] = useState('http://127.0.0.1:8765/mailforge-hook')
  const [webhookEventType, setWebhookEventType] = useState('contact_imported')
  const [secretRef, setSecretRef] = useState('env:MAILFORGE_WEBHOOK_SECRET')
  const [enabled, setEnabled] = useState(false)
  const [localFixture, setLocalFixture] = useState(true)
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const [deliveryResult, setDeliveryResult] = useState<ApiRecord | null>(null)
  const integrationRequest = (path: string, init: RequestInit = {}, bearer = '') => api(path, { ...init, headers: bearer ? { Authorization: `Bearer ${bearer}` } : init.headers })
  const issue = () => onRun(async () => { const result = await api<ApiRecord>('/integrations/clients', { method: 'POST', body: JSON.stringify({ name: clientName, scopes: [clientScope], expires_at: clientExpiry }) }); setIssued(result); return result }, 'Scoped client issued; copy its one-time token now')
  const revoke = (clientRef: string) => onRun(() => api(`/integrations/clients/${clientRef}/revoke`, { method: 'POST' }), 'Scoped client revoked')
  const sendEvent = (bearer: string, message: string) => onRun(async () => {
    const result = await integrationRequest('/integrations/events', { method: 'POST', body: JSON.stringify({ event_id: eventId, source: eventSource, type: incomingEventType, time: eventTime, schema_version: '1', payload: JSON.parse(eventPayload), provenance: { ui: 'integration-hub', qualification: true } }) }, bearer)
    setEventResult(result)
    return result
  }, message)
  const register = () => onRun(() => api('/integrations/webhooks', { method: 'POST', body: JSON.stringify({ name: webhookName, endpoint_url: endpoint, event_types: [webhookEventType], secret_ref: secretRef, enabled, local_fixture: localFixture }) }), 'Webhook subscription saved')
  const toggle = (item: ApiRecord) => onRun(() => api(`/integrations/webhooks/${item.subscription_ref}/state`, { method: 'POST', body: JSON.stringify({ enabled: !item.enabled }) }), `Webhook ${item.enabled ? 'paused' : 'enabled'}`)
  const previewPayload = (item: ApiRecord) => onRun(async () => { const result = await api<ApiRecord>(`/integrations/webhooks/${item.subscription_ref}/preview?event_type=${encodeURIComponent(item.event_types?.[0] || '')}`); setPreview(result); return result }, 'Webhook payload preview loaded')
  const processDeliveries = () => onRun(async () => { const result = await api<ApiRecord>('/integrations/deliveries/process', { method: 'POST' }); setDeliveryResult(result); return result }, 'Due webhook deliveries processed')
  return <div className="content integrations-view">
    <div className="toolbar"><div><p className="eyebrow teal">INTEGRATION HUB</p><h2>Connect local systems with evidence.</h2><p className="muted">Read-only sources, scoped clients, typed observations, and durable signed delivery. Mailforge stays loopback-only; external 2xx responses are transport observations, not business completion.</p></div><span className="status-chip"><span className="live-dot" /> {clients.length} clients · {subscriptions.length} webhooks</span></div>
    <div className="integration-grid"><section className="panel"><div className="panel-head"><div><h3>Data sources</h3><p className="muted">HTTP profiles are fixed-origin GET sources owned by Data Connections.</p></div><button onClick={() => onNavigate('data-connections')}>Open sources</button></div><div className="metric-list"><div><dt>Configured sources</dt><dd>{data.diagnostics?.sources?.length || 0}</dd></div><div><dt>HTTP capability</dt><dd>JSON · JSONL · CSV</dd></div><div><dt>Downstream</dt><dd>Data Studio snapshots</dd></div></div></section>
      <section className="panel"><div className="panel-head"><div><h3>Integration diagnostics</h3><p className="muted">Durable counts only; credentials and private payloads stay out of this view.</p></div><span className="tag">local evidence</span></div><div className="metric-list"><div><dt>Accepted events</dt><dd>{data.diagnostics?.events?.accepted || 0}</dd></div><div><dt>Duplicate / conflict</dt><dd>{(data.diagnostics?.events?.duplicate || 0) + (data.diagnostics?.events?.conflict || 0)}</dd></div><div><dt>Webhook completed</dt><dd>{data.diagnostics?.deliveries?.completed || 0}</dd></div><div><dt>Pending / ambiguous</dt><dd>{(data.diagnostics?.deliveries?.pending || 0) + (data.diagnostics?.deliveries?.ambiguous || 0)}</dd></div></div></section></div>
    <div className="split"><section className="panel"><div className="panel-head"><div><h3>Local clients</h3><p className="muted">Bearer tokens are shown once, hashed at rest, scoped, expiring, and revocable.</p></div></div><label>Client name<input value={clientName} onChange={event => setClientName(event.target.value)} /></label><label>Capability<select value={clientScope} onChange={event => setClientScope(event.target.value)}><option>INGEST_LOCAL_EVENT</option><option>READ_EXTERNAL_DATA</option><option>INSPECT_INTEGRATION</option><option>START_APPROVED_JOB</option></select></label><label>Expiry<input value={clientExpiry} onChange={event => setClientExpiry(event.target.value)} /></label><button className="primary full" onClick={issue}>Issue scoped client</button>{issued && <div className="one-time-token" role="status"><strong>Copy this token now</strong><code>{issued.token}</code><small>It will not be returned again. Store it in the calling local application, not a URL.</small><label>Bearer token for this session<input aria-label="Integration bearer token" value={token} onChange={event => setToken(event.target.value)} /></label></div>}<div className="list-stack">{clients.map(client => <div className="list-row" key={client.client_ref}><span><strong>{client.name}</strong><small>{client.client_ref} · {(client.scopes || []).join(', ')} · {client.revoked_at ? 'revoked' : 'active'}</small></span><div className="button-row"><span className="tag">{client.expires_at?.slice(0, 10)}</span>{!client.revoked_at && <button onClick={() => revoke(client.client_ref)}>Revoke</button>}</div></div>)}</div></section>
      <section className="panel"><div className="panel-head"><div><h3>Webhook subscriptions</h3><p className="muted">Enable deliberately. Payloads use stable IDs and HMAC-SHA256 signatures.</p></div></div><label>Name<input value={webhookName} onChange={event => setWebhookName(event.target.value)} /></label><label>Receiver endpoint<input aria-label="Webhook endpoint" value={endpoint} onChange={event => setEndpoint(event.target.value)} /></label><label>Event family<select aria-label="Webhook event type" value={webhookEventType} onChange={event => setWebhookEventType(event.target.value)}><option>contact_imported</option><option>list_processing_completed</option><option>data_connection_snapshot_completed</option><option>trusted_inbound_reconciled</option></select></label><label>Secret reference<input value={secretRef} onChange={event => setSecretRef(event.target.value)} /><small className="muted">Reference only; secret values never enter browser state or reports.</small></label><label className="check-line"><input type="checkbox" checked={localFixture} onChange={event => setLocalFixture(event.target.checked)} /> Allow loopback fixture receiver</label><label className="check-line"><input type="checkbox" checked={enabled} onChange={event => setEnabled(event.target.checked)} /> Enable after destination review</label><button className="primary full" onClick={register}>Register subscription</button><div className="list-stack">{subscriptions.map(item => <div className="list-row" key={item.subscription_ref}><span><strong>{item.name}</strong><small>{item.endpoint_url} · {(item.event_types || []).join(', ')} · {item.enabled ? 'enabled' : 'paused'}</small></span><div className="button-row"><button onClick={() => void previewPayload(item)}>Preview payload</button><button onClick={() => toggle(item)}>{item.enabled ? 'Pause' : 'Enable'}</button></div></div>)}</div></section></div>
    <div className="split"><section className="panel"><div className="panel-head"><div><h3>Receive a typed event</h3><p className="muted">Exercise authorization, duplicate detection, and durable event identity from the browser.</p></div></div><label>Bearer token<input aria-label="Event bearer token" value={token} onChange={event => setToken(event.target.value)} placeholder="Paste the one-time token" /></label><label>Event ID<input aria-label="Integration event ID" value={eventId} onChange={event => setEventId(event.target.value)} /></label><label>Source<input aria-label="Integration event source" value={eventSource} onChange={event => setEventSource(event.target.value)} /></label><label>Event type<select aria-label="Integration event type" value={incomingEventType} onChange={event => setIncomingEventType(event.target.value)}><option>approved_local_operation_completed</option><option>approved_business_record_changed</option><option>external_dataset_available</option><option>external_application_status_reported</option></select></label><label>Occurred at<input aria-label="Integration event time" value={eventTime} onChange={event => setEventTime(event.target.value)} /></label><label>Payload JSON<textarea aria-label="Integration event payload" rows={4} value={eventPayload} onChange={event => setEventPayload(event.target.value)} /></label><div className="button-row"><button className="primary" disabled={!token} onClick={() => sendEvent(token, 'Authorized typed event recorded')}>Send authorized event</button><button onClick={() => sendEvent('', 'Unauthorized event rejected')}>Send unauthorized event</button><button onClick={() => sendEvent(token, 'Repeat event evaluated')}>Repeat event</button></div>{eventResult && <div className="preview-box" role="status"><strong>{eventResult.outcome}</strong><span>Event record {eventResult.event_record_id || eventResult.conflict_id || 'not created'}</span></div>}</section>
      <section className="panel"><div className="panel-head"><div><h3>Delivery controls</h3><p className="muted">Inspect a signed payload, then process due deliveries. Retry and ambiguity remain durable states.</p></div><button className="primary" onClick={processDeliveries}>Process due deliveries</button></div>{preview ? <div className="preview-box" role="status"><strong>{preview.event_type} · {preview.bytes} bytes</strong><pre className="preview-json">{JSON.stringify(preview.payload, null, 2)}</pre></div> : <Empty text="Choose Preview payload on a subscription to inspect its bounded body." />}{deliveryResult && <div className="preview-box" role="status"><strong>{deliveryResult.items?.length || 0} delivery attempts processed</strong><span>{deliveryResult.items?.map((item: ApiRecord) => `${item.state} · ${item.attempt}`).join(' · ')}</span></div>}</section></div>
    <div className="split"><section className="panel table-panel"><div className="panel-head"><div><h3>Incoming events</h3><p className="muted">External observations are authenticated but never trusted as SMTP, consent, or unsubscribe evidence.</p></div><span className="tag">{events.length} shown</span></div>{events.length ? <table><thead><tr><th>Event</th><th>Type</th><th>Outcome</th><th>Trust</th></tr></thead><tbody>{events.map(event => <tr key={event.id}><td><strong>{event.event_id}</strong><small className="table-subline">{event.source_identity}</small></td><td>{event.event_type}</td><td>{event.outcome}</td><td>{event.trust_class}</td></tr>)}</tbody></table> : <Empty text="No authenticated integration observations yet." />}</section><section className="panel table-panel"><div className="panel-head"><div><h3>Delivery history</h3><p className="muted">At-least-once delivery with bounded retries and visible ambiguous outcomes.</p></div><span className="tag">{deliveries.length} shown</span></div>{deliveries.length ? <table><thead><tr><th>Event</th><th>Status</th><th>Attempts</th><th>HTTP</th></tr></thead><tbody>{deliveries.map(delivery => <tr key={delivery.id}><td>{delivery.event_type}<small className="table-subline">{delivery.event_id}</small></td><td>{delivery.status}{delivery.ambiguous ? ' · ambiguous' : ''}</td><td>{delivery.attempt_number}</td><td>{delivery.last_http_status || '—'}</td></tr>)}</tbody></table> : <Empty text="No webhook deliveries planned yet." />}</section></div>
    <section className="panel"><h3>Operational boundary</h3><p className="muted">Local fixtures are synthetic. The Hub never exposes arbitrary HTTP methods, shell execution, public callbacks, unrestricted workflow authority, or a path to unrestricted live email sending.</p></section>
  </div>
}

function Stat({ label, value, tone = '' }: { label: string, value: string | number, tone?: string }) { return <div className={`stat-card ${tone}`}><span>{label}</span><strong>{value}</strong><small>durable local state</small></div> }

function Reports({ data, onNavigate }: { data: ApiRecord, onNavigate: (view: string) => void }) {
  const [summary, setSummary] = useState<ApiRecord>(data)
  const [preset, setPreset] = useState('last_7_days')
  const [timezone, setTimezone] = useState('UTC')
  const [start, setStart] = useState('')
  const [end, setEnd] = useState('')
  const [providerRef, setProviderRef] = useState('')
  const [workflowId, setWorkflowId] = useState('')
  const [sourceRef, setSourceRef] = useState('')
  const [accountRef, setAccountRef] = useState('')
  const [folder, setFolder] = useState('')
  const [jobKind, setJobKind] = useState('')
  const [section, setSection] = useState('summary')
  const [detail, setDetail] = useState<ApiRecord | null>(null)
  const [detailBusy, setDetailBusy] = useState(false)
  const [detailError, setDetailError] = useState('')
  const [summaryError, setSummaryError] = useState('')
  const metrics = summary.metrics || {}
  const campaigns = metrics.campaigns || {}
  const providers = metrics.providers || {}
  const inbound = metrics.inbound || {}
  const workflows = metrics.workflows || {}
  const processing = metrics.processing || {}
  const messageStudio = metrics.message_studio || {}
  const attemptTotal = campaigns.attempts?.total ?? 0
  const accepted = campaigns.attempts?.accepted ?? 0
  const previousCampaigns = summary.previous?.campaigns?.campaign_count
  const campaignDelta = previousCampaigns === undefined ? null : (campaigns.campaign_count ?? 0) - previousCampaigns

  useEffect(() => { setSummary(data) }, [data])
  const reportQuery = (nextPreset = preset, nextTimezone = timezone, nextStart = start, nextEnd = end) => {
    const params = new URLSearchParams({ preset: nextPreset, timezone: nextTimezone })
    if (nextStart) params.set('start', nextStart)
    if (nextEnd) params.set('end', nextEnd)
    if (providerRef) params.set('provider_ref', providerRef)
    if (workflowId) params.set('workflow_id', workflowId)
    if (sourceRef) params.set('source_ref', sourceRef)
    if (accountRef) params.set('account_ref', accountRef)
    if (folder) params.set('folder', folder)
    if (jobKind) params.set('job_kind', jobKind)
    return params
  }
  const loadDetail = async (nextSection: string, nextPreset = preset, nextTimezone = timezone, nextStart = start, nextEnd = end) => {
    if (nextSection === 'summary') return
    setDetailBusy(true); setDetailError('')
    try {
      const params = reportQuery(nextPreset, nextTimezone, nextStart, nextEnd)
      setDetail(await api<ApiRecord>(`/reports/${nextSection}?${params}`))
    } catch (err) {
      setDetail(null); setDetailError(err instanceof Error ? err.message : 'Unable to load this report section')
    } finally { setDetailBusy(false) }
  }
  const reload = async (nextPreset = preset, nextTimezone = timezone, nextStart = start, nextEnd = end) => {
    if (nextPreset === 'custom' && (!nextStart || !nextEnd)) return
    const params = reportQuery(nextPreset, nextTimezone, nextStart, nextEnd)
    setSummaryError('')
    try {
      setSummary(await api<ApiRecord>(`/reports/summary?${params}`))
      if (section !== 'summary') await loadDetail(section, nextPreset, nextTimezone, nextStart, nextEnd)
    } catch (err) {
      setSummaryError(err instanceof Error ? err.message : 'Unable to refresh this report')
    }
  }
  const selectSection = async (next: string) => {
    setSection(next); setDetail(null); setDetailError('')
    await loadDetail(next)
  }
  const sections = [['summary', 'Summary'], ['campaigns', 'Campaigns'], ['providers', 'Providers'], ['workflows', 'Workflows'], ['inbound', 'Inbound'], ['jobs', 'Processing']]
  const detailRows = section === 'workflows' ? (detail?.runs || []) : detail?.items || detail?.accounts || detail?.messages || detail?.jobs || []
  const exportParams = reportQuery(); exportParams.set('report_type', section === 'jobs' ? 'jobs' : section); exportParams.set('format', 'csv')
  const workbench = section === 'inbound' ? 'inbound' : section === 'workflows' ? 'automations' : section === 'jobs' ? (jobKind === 'list_tools' ? 'list-tools' : 'data-studio') : section === 'providers' ? 'providers' : 'campaigns'
  return <div className="content reports-view">
    <div className="toolbar"><div><p className="eyebrow teal">OPERATIONAL INTELLIGENCE</p><h2>Reports &amp; Insights</h2><p className="muted">A read-only view of durable local observations across campaigns, providers, inbound evidence, workflows, and processing jobs.</p></div><div className="toolbar-actions"><label>Range<select aria-label="Report range" value={preset} onChange={event => { const next = event.target.value; setPreset(next); void reload(next, timezone, start, end) }}><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="last_7_days">Last 7 days</option><option value="last_30_days">Last 30 days</option><option value="custom">Custom</option></select></label><label>Timezone<input aria-label="Report timezone" value={timezone} onChange={event => setTimezone(event.target.value)} onBlur={() => void reload(preset, timezone, start, end)} /></label><button onClick={() => void reload()} aria-label="Refresh report">Refresh</button></div></div>
    {preset === 'custom' && <div className="report-range-fields"><label>Start date<input aria-label="Report start date" type="date" value={start} onChange={event => { setStart(event.target.value); if (end) void reload('custom', timezone, event.target.value, end) }} /></label><label>End date<input aria-label="Report end date" type="date" value={end} onChange={event => { setEnd(event.target.value); if (start) void reload('custom', timezone, start, event.target.value) }} /></label></div>}
    <div className="report-filter-fields"><label>Provider ref<input aria-label="Report provider filter" value={providerRef} onChange={event => setProviderRef(event.target.value)} placeholder="Any provider" /></label><label>Workflow id<input aria-label="Report workflow filter" value={workflowId} onChange={event => setWorkflowId(event.target.value)} placeholder="Any workflow" /></label><label>Inbound source<input aria-label="Report source filter" value={sourceRef} onChange={event => setSourceRef(event.target.value)} placeholder="Any source" /></label><label>Account ref<input aria-label="Report account filter" value={accountRef} onChange={event => setAccountRef(event.target.value)} placeholder="Any account" /></label><label>Folder<input aria-label="Report folder filter" value={folder} onChange={event => setFolder(event.target.value)} placeholder="Any folder" /></label><label>Job kind<select aria-label="Report job filter" value={jobKind} onChange={event => setJobKind(event.target.value)}><option value="">All jobs</option><option value="data_studio">Data Studio</option><option value="list_tools">List Tools</option></select></label><button onClick={() => void reload()} aria-label="Apply report filters">Apply filters</button></div>
    <div className="report-boundary" role="note"><strong>Evidence boundary:</strong> local durable observations only. SMTP acceptance is not inbox delivery, and synthetic data does not qualify a real provider.</div>
    {summaryError && <div className="error" role="alert">{summaryError}</div>}
    <div className="report-tabs" role="tablist" aria-label="Report sections">{sections.map(([id, label]) => <button key={id} role="tab" aria-selected={section === id} className={section === id ? 'active' : ''} onClick={() => void selectSection(id)}>{label}</button>)}</div>
    {section === 'summary' ? <>
      <div className="stat-grid report-stats"><Stat label="Campaigns" value={campaigns.campaign_count ?? 0} tone="teal" /><Stat label="Submission attempts" value={attemptTotal} /><Stat label="Accepted submissions" value={accepted} tone="teal" /><Stat label="Ambiguous outcomes" value={campaigns.attempts?.ambiguous ?? 0} tone="amber" /><Stat label="Pending inbound reviews" value={inbound.pending_reviews ?? 0} tone="amber" /><Stat label="Waiting workflow runs" value={workflows.waiting?.count ?? 0} /></div>
      {campaignDelta !== null && <p className="report-comparison" role="status">Compared with the previous matching period: campaigns {campaignDelta >= 0 ? '+' : ''}{campaignDelta} ({previousCampaigns ?? 0} previously).</p>}
      <div className="split report-panels"><section className="panel"><div className="panel-head"><div><h3>Signal coverage</h3><p className="muted">Counts are keyed to the selected range and source timestamp.</p></div></div><dl className="metric-list"><div><dt>Inbound messages</dt><dd>{inbound.messages ?? 0}</dd></div><div><dt>Provider diagnostics</dt><dd>{providers.diagnostics?.reduce((total: number, item: ApiRecord) => total + (item.count || 0), 0) ?? 0}</dd></div><div><dt>Data Studio artifacts</dt><dd>{processing.artifact_count ?? 0}</dd></div><div><dt>Message revisions</dt><dd>{messageStudio.revisions_created ?? 0}</dd></div></dl></section><section className="panel"><div className="panel-head"><div><h3>Deterministic insights</h3><p className="muted">Evidence-linked observations; no opaque recommendations.</p></div></div>{metrics.insights?.length ? <div className="insight-list">{metrics.insights.map((insight: ApiRecord) => <article className={`insight ${insight.severity}`} key={insight.id}><strong>{insight.title}</strong><p>{insight.observation}</p><small>Next: {insight.next_action}</small>{insight.evidence?.record_ids?.length ? <small>Evidence records: {insight.evidence.record_ids.join(', ')}</small> : null}</article>)}</div> : <Empty text="No attention signals in this range." />}</section></div>
      <section className="panel"><div className="panel-head"><div><h3>Explore the evidence</h3><p className="muted">Open a bounded drilldown without leaving the reporting surface.</p></div></div><div className="button-row report-links"><button onClick={() => void selectSection('campaigns')}>Campaign outcomes</button><button onClick={() => void selectSection('providers')}>Provider evidence</button><button onClick={() => void selectSection('inbound')}>Inbound trust</button><button onClick={() => void selectSection('jobs')}>Processing jobs</button><button onClick={() => onNavigate('activity')}>Open operational ledger</button></div></section>
    </> : <section className="panel table-panel"><div className="panel-head"><div><h3>{sections.find(([id]) => id === section)?.[1]}</h3><p className="muted">{detailBusy ? 'Loading bounded records…' : 'Paginated durable records; message bodies and credentials are excluded.'}</p></div>{detail && <a className="text-button" href={`/api/v1/reports/export?${exportParams}`}>Export CSV</a>}</div>{detailError && <div className="error" role="alert">{detailError}</div>}{detailBusy ? <div className="loading" role="status">Loading report section…</div> : detailRows.length ? <table><thead><tr><th>Record</th><th>Status</th><th>Observed</th><th>Evidence</th><th>Inspect</th></tr></thead><tbody>{detailRows.map((item: ApiRecord, index: number) => <tr key={item.id || item.ref || index}><td><strong>{item.name || item.display_name || item.source_ref || item.workflow_id || item.id || 'Record'}</strong><small className="table-subline">{item.ref || item.kind || item.profile_ref || item.account_ref || item.id || 'local record'}</small></td><td>{item.status || item.outcome || item.trust_status || 'observed'}</td><td>{item.created_at || item.observed_at || item.acquired_at || item.started_at || '—'}</td><td>{item.evidence_class || 'durable local observation'}</td><td><button className="text-button" onClick={() => onNavigate(workbench)}>Open {workbench.replace('-', ' ')}</button></td></tr>)}</tbody></table> : <Empty text="No durable records match this range." />}{section === 'workflows' && detail?.workflows?.length ? <div className="report-secondary"><h3>Workflow definitions</h3>{detail.workflows.map((item: ApiRecord) => <p key={item.id}><strong>{item.name}</strong> · {item.status} · updated {item.updated_at}</p>)}</div> : null}</section>}
  </div>
}

function DataStudio({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [files, setFiles] = useState<File[]>([])
  const [recipeName, setRecipeName] = useState('Normalize and classify contacts')
  const [selected, setSelected] = useState<ApiRecord | null>(null)
  const [savedFingerprint, setSavedFingerprint] = useState('')
  const [definition, setDefinition] = useState<ApiRecord>({ steps: [{ type: 'normalize', fields: ['email'], operation: 'email' }, { type: 'dedupe', fields: ['email'] }] })
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const [job, setJob] = useState<ApiRecord | null>(null)
  const [lists, setLists] = useState<ApiRecord[]>([])
  const [destinationList, setDestinationList] = useState('')
  const [campaigns, setCampaigns] = useState<ApiRecord[]>([])
  const [campaignId, setCampaignId] = useState('')
  const [emailField, setEmailField] = useState('email')
  const [nameField, setNameField] = useState('name')
  const [contactSource, setContactSource] = useState('')
  const [contactField, setContactField] = useState('')
  const [contactFields, setContactFields] = useState<ApiRecord[]>([])
  const [overwrite, setOverwrite] = useState(false)
  const [reconcilePreview, setReconcilePreview] = useState<ApiRecord | null>(null)
  const [importOutcome, setImportOutcome] = useState<ApiRecord | null>(null)
  const [messageDocuments, setMessageDocuments] = useState<ApiRecord[]>([])
  const [messageRevision, setMessageRevision] = useState('')
  const [messagePreview, setMessagePreview] = useState<ApiRecord | null>(null)
  const [preparedBatch, setPreparedBatch] = useState<ApiRecord | null>(null)
  const [combineMode, setCombineMode] = useState('append')
  const [joinKey, setJoinKey] = useState('email')
  const [outputFormat, setOutputFormat] = useState('jsonl')
  const recipes: ApiRecord[] = data.items || []
  const steps: ApiRecord[] = definition.steps || []
  useEffect(() => {
    void api<ApiRecord>('/lists').then(result => setLists(result.items || []))
    void api<ApiRecord>('/fields').then(result => setContactFields(result.items || []))
    void api<ApiRecord>('/campaigns').then(result => setCampaigns(result.items || []))
    void api<ApiRecord>('/message-studio/documents').then(async result => setMessageDocuments(await Promise.all((result.items || []).map((item: ApiRecord) => api<ApiRecord>(`/message-studio/documents/${item.id}`)))))
  }, [])
  const reloadRecipe = async (id: string) => {
    const result = await api<ApiRecord>(`/data-studio/recipes/${id}`)
    setSelected(result); setDefinition(result.revision.definition); setSavedFingerprint(JSON.stringify(result.revision.definition))
  }
  const updateStep = (index: number, changes: ApiRecord) => setDefinition(current => ({ ...current, steps: current.steps.map((step: ApiRecord, position: number) => position === index ? { ...step, ...changes } : step) }))
  const addStep = (type: string) => {
    const defaults: Record<string, ApiRecord> = {
      normalize: { type, fields: ['email'], operation: 'email' },
      dedupe: { type, fields: ['email'] },
      filter: { type, condition: { field: 'email', op: 'present' } },
      computed: { type, field: 'full_name', expression: { kind: 'concat', fields: ['first', 'last'], separator: ' ' } },
      provider_classify: { type, field: 'email', output_field: 'provider' },
      validate: { type, required: ['email'], allowed: {} },
    }
    setDefinition(current => ({ ...current, steps: [...(current.steps || []), defaults[type]] }))
  }
  const effectiveDefinition = { ...definition, output: { ...(definition.output || {}), format: outputFormat }, ...(files.length > 1 ? { combine: { operation: combineMode, keys: [joinKey], join_type: 'left', key_normalization: joinKey === 'email' ? 'email' : 'trim' } } : {}) }
  const recipeDirty = Boolean(
    selected && savedFingerprint && savedFingerprint !== JSON.stringify(effectiveDefinition),
  )
  const saveRecipe = () => onRun(async () => {
    const result = selected ? await api<ApiRecord>(`/data-studio/recipes/${selected.id}/revisions`, { method: 'POST', body: JSON.stringify({ definition: effectiveDefinition, expected_revision_id: selected.current_revision_id }) }) : await api<ApiRecord>('/data-studio/recipes', { method: 'POST', body: JSON.stringify({ name: recipeName, description: 'Pinned local transformation recipe', definition: effectiveDefinition }) })
    const saved = result.revision?.definition || effectiveDefinition
    setSelected(result); setDefinition(saved); setSavedFingerprint(JSON.stringify(saved))
  }, selected ? 'Recipe revision saved' : 'Recipe saved')
  const inspect = () => files.length && onRun(async () => { setPreview(files.length > 1 ? await uploadMany('/data-studio/preview-multi', files, { definition: JSON.stringify(effectiveDefinition) }) : await uploadWithFields('/data-studio/preview', files[0], { definition: JSON.stringify(effectiveDefinition) })) }, 'Preview ready')
  const run = () => files.length && selected && onRun(async () => {
    const created = files.length > 1 ? await uploadMany('/data-studio/jobs-multi?recipe_revision_id=' + encodeURIComponent(selected.current_revision_id), files) : await upload('/data-studio/jobs', files[0], '?recipe_revision_id=' + encodeURIComponent(selected.current_revision_id))
    await api(`/data-studio/jobs/${created.id}/start`, { method: 'POST' })
    for (let attempt = 0; attempt < 80; attempt += 1) {
      const current = await api<ApiRecord>(`/data-studio/jobs/${created.id}`)
      if (!['pending', 'running'].includes(current.status)) {
        setJob(current)
        if (current.status !== 'completed') throw new Error(current.error_message || `Processing job ${current.status}`)
        return
      }
      await new Promise(resolve => window.setTimeout(resolve, 50))
    }
    const current = await api<ApiRecord>(`/data-studio/jobs/${created.id}`)
    setJob(current)
    throw new Error('Processing is still running; refresh the job to inspect progress')
  }, 'Processing job completed')
  const outputArtifact = job?.artifacts?.find((artifact: ApiRecord) => artifact.kind === 'output')
  const mapping = { [emailField]: 'contact.email', ...(contactSource && contactField && contactSource !== emailField ? { [contactSource]: contactField } : {}) }
  const messageMapping = { [emailField]: 'email', ...(nameField ? { [nameField]: 'name' } : {}) }
  const previewContacts = () => job && outputArtifact && destinationList && onRun(async () => { setImportOutcome(null); setReconcilePreview(await api(`/data-studio/jobs/${job.id}/artifacts/${outputArtifact.id}/contacts/preview`, { method: 'POST', body: JSON.stringify({ list_id: destinationList, mappings: mapping, overwrite, source_ref: `data-studio:${job.id}` }) })) }, 'Contact reconciliation preview ready')
  const importContacts = () => job && outputArtifact && destinationList && reconcilePreview?.valid && onRun(async () => setImportOutcome(await api(`/data-studio/jobs/${job.id}/artifacts/${outputArtifact.id}/contacts`, { method: 'POST', body: JSON.stringify({ list_id: destinationList, mappings: mapping, overwrite, source_ref: `data-studio:${job.id}` }) })), 'Contacts imported with explicit reconciliation policy')
  const previewMessage = () => job && outputArtifact && messageRevision && onRun(async () => setMessagePreview(await api(`/data-studio/jobs/${job.id}/artifacts/${outputArtifact.id}/message-preview`, { method: 'POST', body: JSON.stringify({ revision_id: messageRevision, field_mapping: messageMapping }) })), 'Message personalization preview rendered')
  const prepareCampaign = () => { const campaign = campaigns.find(item => item.id === campaignId); return job && outputArtifact && campaignId && campaign?.message_revision_id && onRun(async () => setPreparedBatch(await api(`/campaigns/${campaignId}/prepare-data-studio`, { method: 'POST', body: JSON.stringify({ source_job_id: job.id, source_artifact_id: outputArtifact.id, recipe_revision_id: job.recipe_revision_id, message_revision_id: campaign.message_revision_id, field_mapping: messageMapping }) })), 'Recipient batch prepared from pinned Data Studio snapshot') }
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">DATA STUDIO</p><p className="muted">Transform local structured data with a pinned, explainable recipe. Preview never changes the source.</p></div><span className="status-chip">{recipes.length} recipes</span></div>
    <div className="split"><section className="panel"><div className="panel-head"><div><h3>Source and recipe</h3><p className="muted">CSV, TSV, JSON, JSONL, or line-based TXT · bounded local processing</p></div></div><label className="file-drop">{files.length ? `${files.length} source${files.length === 1 ? '' : 's'} selected` : 'Choose one or more structured data files'}<input aria-label="Data Studio source file" multiple type="file" accept=".csv,.tsv,.json,.jsonl,.txt" onChange={event => setFiles(Array.from(event.target.files || []))} /></label>{files.length > 1 && <div className="inline-fields"><label>Combine operation<select aria-label="Data Studio combine operation" value={combineMode} onChange={event => setCombineMode(event.target.value)}><option value="append">Append</option><option value="union">Compatible union</option><option value="join">Left join</option><option value="intersect">Intersect</option><option value="subtract">Subtract</option></select></label><label>Key field<input aria-label="Data Studio join key" value={joinKey} onChange={event => setJoinKey(event.target.value)} /></label></div>}<div className="inline-fields"><label>Export format<select aria-label="Data Studio export format" value={outputFormat} onChange={event => setOutputFormat(event.target.value)}><option value="jsonl">JSONL</option><option value="json">JSON</option><option value="csv">CSV</option><option value="tsv">TSV</option><option value="txt">TXT</option></select></label><label>Recipe name<input value={recipeName} onChange={event => setRecipeName(event.target.value)} /></label></div>{recipeDirty && <p className="warning-copy" role="status">Preview reflects unsaved controls; processing uses the selected saved revision.</p>}<div className="button-row"><button disabled={!files.length} onClick={inspect}>Preview source</button><button className="primary" disabled={!files.length || !selected} title={recipeDirty ? 'Processing uses the selected saved revision; save changes to process the previewed recipe' : undefined} onClick={run}>Start processing</button></div></section><section className="panel"><div className="panel-head"><div><h3>Saved recipes</h3><p className="muted">Runs pin the selected revision.</p></div></div>{recipes.length ? <div className="list-stack">{recipes.map(recipe => <button className={selected?.id === recipe.id ? 'list-row selected' : 'list-row'} key={recipe.id} onClick={() => void reloadRecipe(recipe.id)}><span><strong>{recipe.name}</strong><small>{recipe.status} · {recipe.current_revision_id?.slice(0, 8)}</small></span><b>Open →</b></button>)}</div> : <Empty text="Save a recipe after choosing your first steps." />}<button className="primary full" onClick={saveRecipe}>Save current recipe</button></section></div>
    <section className="panel"><div className="panel-head"><div><h3>Ordered processing steps</h3><p className="muted">Each step is typed and reviewed before execution; no expressions run as Python or JavaScript.</p></div><select aria-label="Add Data Studio step" defaultValue="" onChange={event => { if (event.target.value) { addStep(event.target.value); event.target.value = '' } }}><option value="">+ Add step</option><option value="normalize">Normalize</option><option value="filter">Filter</option><option value="computed">Computed field</option><option value="dedupe">Remove duplicates</option><option value="provider_classify">Classify provider</option><option value="validate">Validate fields</option></select></div>{steps.map((step, index) => <article className="studio-block" key={index}><div className="studio-block-head"><strong>{index + 1}. {step.type}</strong><button aria-label={`Remove step ${index + 1}`} onClick={() => setDefinition(current => ({ ...current, steps: current.steps.filter((_: ApiRecord, position: number) => position !== index) }))}>×</button></div>{step.type === 'normalize' && <div className="inline-fields"><label>Fields<input value={(step.fields || []).join(', ')} onChange={event => updateStep(index, { fields: event.target.value.split(',').map((value: string) => value.trim()).filter(Boolean) })} /></label><label>Operation<select value={step.operation || 'whitespace'} onChange={event => updateStep(index, { operation: event.target.value })}><option value="email">Email address</option><option value="whitespace">Trim whitespace</option><option value="lower">Lowercase</option><option value="upper">Uppercase</option></select></label></div>}{step.type === 'dedupe' && <label>Key fields<input value={(step.fields || []).join(', ')} onChange={event => updateStep(index, { fields: event.target.value.split(',').map((value: string) => value.trim()) })} /></label>}{step.type === 'computed' && <div className="inline-fields"><label>Output field<input value={step.field || ''} onChange={event => updateStep(index, { field: event.target.value })} /></label><label>Expression<select value={step.expression?.kind || 'concat'} onChange={event => updateStep(index, { expression: { ...step.expression, kind: event.target.value } })}><option value="concat">Combine fields</option><option value="email_domain">Email domain</option><option value="provider_classify">Provider classification</option></select></label></div>}{step.type === 'filter' && <div className="inline-fields"><label>Field<input value={step.condition?.field || ''} onChange={event => updateStep(index, { condition: { ...step.condition, field: event.target.value } })} /></label><label>Operator<select value={step.condition?.op || 'present'} onChange={event => updateStep(index, { condition: { ...step.condition, op: event.target.value } })}><option value="present">Present</option><option value="missing">Missing</option><option value="contains">Contains</option><option value="equals">Equals</option></select></label></div>}{step.type === 'provider_classify' && <label>Email field<input value={step.field || 'email'} onChange={event => updateStep(index, { field: event.target.value })} /></label>}{step.type === 'validate' && <label>Required fields<input value={(step.required || []).join(', ')} onChange={event => updateStep(index, { required: event.target.value.split(',').map((value: string) => value.trim()).filter(Boolean) })} /></label>}</article>)}</section>
    {job && outputArtifact && <section className="panel"><div className="panel-head"><div><h3>Completed output</h3><p className="muted">{job.output_count} rows · {job.rejected_count} rejected · revision {job.recipe_revision_id?.slice(0, 8)}</p></div><a className="button primary" href={`/api/v1/data-studio/jobs/${job.id}/artifacts/${outputArtifact.id}`}>Download {outputArtifact.filename}</a></div><div className="inline-fields"><label>Email source field<input aria-label="Contact email source field" value={emailField} onChange={event => { setEmailField(event.target.value); setReconcilePreview(null) }} /></label><label>Name source field<input aria-label="Contact name source field" value={nameField} onChange={event => setNameField(event.target.value)} /></label><label>Additional contact source field<input aria-label="Additional contact source field" value={contactSource} onChange={event => { setContactSource(event.target.value); setReconcilePreview(null) }} placeholder="plan" /></label><label>Target contact field<select aria-label="Target contact field" value={contactField} onChange={event => { setContactField(event.target.value); setReconcilePreview(null) }}><option value="">Choose a typed field</option>{contactFields.map(field => <option key={field.id} value={field.id}>{field.label} · {field.machine_key}</option>)}</select></label><label>Contact destination<select aria-label="Contact destination list" value={destinationList} onChange={event => { setDestinationList(event.target.value); setReconcilePreview(null) }}><option value="">Choose a list</option>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label><label><input type="checkbox" checked={overwrite} onChange={event => { setOverwrite(event.target.checked); setReconcilePreview(null) }} /> Allow explicit overwrite of conflicting fields</label><button disabled={!destinationList} onClick={previewContacts}>Validate mapping</button><button className="primary" disabled={!destinationList || !reconcilePreview?.valid} onClick={importContacts}>Import reconciled contacts</button></div>{reconcilePreview && <div className="preview-box" role="status"><strong>{reconcilePreview.valid ? 'Mapping is valid' : 'Mapping needs attention'}</strong><span>{reconcilePreview.records} rows · {reconcilePreview.invalid?.length || 0} invalid · {reconcilePreview.conflicts?.length || 0} existing-field conflicts</span>{(reconcilePreview.invalid?.length || reconcilePreview.conflicts?.length) ? <details><summary>Show row-level feedback</summary><pre className="preview-json">{JSON.stringify({ invalid: reconcilePreview.invalid || [], conflicts: reconcilePreview.conflicts || [] }, null, 2)}</pre></details> : null}</div>}{importOutcome && <div className="preview-box" role="status"><strong>Import completed</strong><span>{importOutcome.created || 0} created · {importOutcome.filled || 0} fields filled · {importOutcome.preserved || 0} preserved · {importOutcome.invalid?.length || 0} invalid · {importOutcome.conflicts?.length || 0} conflicts</span></div>}<div className="inline-fields"><label>Message revision<select aria-label="Message Studio revision" value={messageRevision} onChange={event => setMessageRevision(event.target.value)}><option value="">Choose a published message</option>{messageDocuments.flatMap(document => document.published ? [{ id: document.published.id, label: document.name }] : []).map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><button disabled={!messageRevision} onClick={previewMessage}>Preview personalization</button><label>Prepared campaign<select aria-label="Prepared campaign" value={campaignId} onChange={event => setCampaignId(event.target.value)}><option value="">Choose a campaign</option>{campaigns.filter(campaign => campaign.message_revision_id).map(campaign => <option key={campaign.id} value={campaign.id}>{campaign.name}</option>)}</select></label><button className="primary" disabled={!campaignId} onClick={prepareCampaign}>Prepare recipient batch</button></div><p className="muted">Preparation pins the source artifact, recipe revision, field mapping, recipient row, message revision, and rendered content. Later edits do not rewrite this batch.</p></section>}
    {messagePreview && <section className="panel"><div className="panel-head"><div><h3>Message Studio preview</h3><p className="muted">Snapshot pinned to the selected artifact and published message revision.</p></div></div><p><strong>{messagePreview.subject}</strong></p><pre className="preview-json">{messagePreview.text}</pre></section>}
    {preparedBatch && <section className="panel" role="status"><div className="panel-head"><div><h3>Prepared recipient batch</h3><p className="muted">The campaign now points at an immutable Data Studio snapshot.</p></div></div><p>{preparedBatch.data_snapshot?.recipients?.length || 0} recipients pinned · artifact {preparedBatch.data_snapshot?.artifact_sha256?.slice(0, 12)} · prepared {preparedBatch.prepared || 0} messages</p></section>}
    {preview && <section className="panel table-panel"><div className="panel-head"><div><h3>Preview</h3><p className="muted">Preview only · {preview.counts?.input || 0} input · {preview.counts?.output || 0} output · {preview.counts?.removed || 0} removed · {preview.counts?.errors || 0} validation errors</p></div></div><table><thead><tr>{Object.keys(preview.rows?.[0] || {}).filter(key => !key.startsWith('__')).map(key => <th key={key}>{key}</th>)}</tr></thead><tbody>{(preview.rows || []).slice(0, 20).map((row: ApiRecord, index: number) => <tr key={index}>{Object.keys(preview.rows?.[0] || {}).filter(key => !key.startsWith('__')).map(key => <td key={key}>{typeof row[key] === 'object' ? JSON.stringify(row[key]) : String(row[key] ?? '—')}</td>)}</tr>)}</tbody></table></section>}
  </div>
}

type StudioBlock = ApiRecord & { type: string }

function MessageStudio({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [selected, setSelected] = useState('')
  const [detail, setDetail] = useState<ApiRecord | null>(null)
  const [document, setDocument] = useState<ApiRecord | null>(null)
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const [contacts, setContacts] = useState<ApiRecord[]>([])
  const [contactId, setContactId] = useState('')
  const [segments, setSegments] = useState<ApiRecord[]>([])
  const [assets, setAssets] = useState<ApiRecord[]>([])
  const items: ApiRecord[] = data.items || []

  const refresh = async (id = selected) => {
    if (!id) return
    const next = await api<ApiRecord>(`/message-studio/documents/${id}`)
    setDetail(next)
    setDocument(next.draft?.document || next.published?.document || null)
  }
  useEffect(() => { void api<ApiRecord>('/contacts').then(result => setContacts(result.items || [])); void api<ApiRecord>('/segments').then(result => setSegments(result.items || [])); void api<ApiRecord>('/message-studio/assets').then(result => setAssets(result.items || [])) }, [])
  useEffect(() => { if (selected) void refresh(selected) }, [selected])

  const update = (changes: ApiRecord) => setDocument(current => current ? ({ ...current, ...changes }) : current)
  const blocks: StudioBlock[] = document?.blocks || []
  const updateBlock = (index: number, changes: ApiRecord) => update({ blocks: blocks.map((block, position) => position === index ? { ...block, ...changes } : block) })
  const addBlock = (type: string) => {
    const defaults: Record<string, ApiRecord> = {
      text: { type: 'text', text: 'Write a clear, useful paragraph.' },
      heading: { type: 'heading', level: 2, text: 'A section heading' },
      list: { type: 'list', items: ['One useful point', 'Another useful point'] },
      button: { type: 'button', label: 'Read more', url: 'https://example.com' },
      divider: { type: 'divider' },
      spacer: { type: 'spacer', height: 24 },
      image: { type: 'image', asset_id: assets.find(item => item.kind === 'image')?.id || '', alt: 'Message image', width: 600 },
      conditional: { type: 'conditional', condition: { segment_id: segments[0]?.id || '' }, if_true: [{ type: 'text', text: 'A message for this audience.' }], if_false: [{ type: 'text', text: 'A general message.' }] },
    }
    update({ blocks: [...blocks, defaults[type]] })
  }
  const moveBlock = (index: number, direction: number) => {
    const target = index + direction
    if (target < 0 || target >= blocks.length) return
    const next = [...blocks]; [next[index], next[target]] = [next[target], next[index]]; update({ blocks: next })
  }
  const create = () => onRun(async () => { const result = await api<ApiRecord>('/message-studio/documents', { method: 'POST', body: JSON.stringify({ name: 'New message', kind: 'message' }) }); setSelected(result.id); await refresh(result.id) }, 'Message draft created')
  const save = () => selected && document && onRun(() => api(`/message-studio/documents/${selected}/save`, { method: 'POST', body: JSON.stringify({ document, expected_revision_id: detail?.current_draft_revision_id }) }).then(() => refresh(selected)), 'Message draft saved')
  const publish = () => selected && onRun(() => api(`/message-studio/documents/${selected}/publish`, { method: 'POST', body: JSON.stringify({ expected_revision_id: detail?.current_draft_revision_id }) }).then(() => refresh(selected)), 'Message revision published')
  const renderPreview = () => document && onRun(async () => { setPreview(await api('/message-studio/preview', { method: 'POST', body: JSON.stringify({ document, contact_id: contactId || null }) })) }, 'Recipient preview rendered')

  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">MESSAGE STUDIO</p><p className="muted">Compose safe, reusable email content. Preview is local and never sends.</p></div><div className="toolbar-actions"><button className="primary" onClick={create}>+ New message</button></div></div><div className="studio-layout"><section className="panel"><div className="panel-head"><div><h3>Message library</h3><p className="muted">Drafts and published revisions</p></div><span className="count-badge">{items.length}</span></div>{items.length ? <div className="list-stack">{items.map(item => <button className={item.id === selected ? 'list-row selected' : 'list-row'} key={item.id} onClick={() => setSelected(item.id)}><span><strong>{item.name}</strong><small>{item.status} · {item.current_published_revision_id ? 'published' : 'draft only'}</small></span><b>Open →</b></button>)}</div> : <Empty text="Create a message to begin composing." />}<label className="file-drop studio-upload">Upload image or attachment<input aria-label="Message asset" type="file" onChange={event => { const file = event.target.files?.[0]; if (file) void onRun(async () => { const result = await upload('/message-studio/assets?kind=' + (file.type.startsWith('image/') ? 'image' : 'attachment'), file); setAssets(current => [result, ...current]) }, 'Asset stored locally') }} /></label></section>{selected && document ? <section className="panel studio-editor"><div className="panel-head"><div><h3>Compose message</h3><p className="muted">Structured blocks keep output email-safe.</p></div><span className="status-chip">{detail?.status || 'draft'}</span></div><label>Message name<input value={document.name || ''} onChange={event => update({ name: event.target.value })} /></label><label>Subject<input value={document.subject || ''} onChange={event => update({ subject: event.target.value })} /></label><label>Preheader <span className="muted">(optional)<input value={document.preheader || ''} onChange={event => update({ preheader: event.target.value })} /></span></label><div className="merge-toolbar" aria-label="Insert merge field"><span>Insert field:</span>{['name', 'email', 'contact.company'].map(field => <button key={field} onClick={() => update({ blocks: [...blocks, { type: 'text', text: `{{ ${field} }}` }] })}>{field}</button>)}</div><div className="studio-blocks">{blocks.map((block, index) => <article className="studio-block" key={index}><div className="studio-block-head"><strong>{block.type}</strong><div className="button-row"><button aria-label="Move block up" onClick={() => moveBlock(index, -1)}>↑</button><button aria-label="Move block down" onClick={() => moveBlock(index, 1)}>↓</button><button aria-label="Remove block" onClick={() => update({ blocks: blocks.filter((_, position) => position !== index) })}>×</button></div></div>{block.type === 'text' && <><label>Paragraph<textarea value={block.text || ''} onChange={event => updateBlock(index, { text: event.target.value })} rows={4} /></label><div className="inline-fields"><label><input type="checkbox" checked={Boolean(block.bold)} onChange={event => updateBlock(index, { bold: event.target.checked })} /> Bold</label><label><input type="checkbox" checked={Boolean(block.italic)} onChange={event => updateBlock(index, { italic: event.target.checked })} /> Italic</label><label>Align<select value={block.align || 'left'} onChange={event => updateBlock(index, { align: event.target.value })}><option>left</option><option>center</option><option>right</option></select></label></div></>}{block.type === 'heading' && <label>Heading<textarea value={block.text || ''} onChange={event => updateBlock(index, { text: event.target.value })} rows={2} /></label>}{block.type === 'list' && <label>List items<textarea value={(block.items || []).join('\n')} onChange={event => updateBlock(index, { items: event.target.value.split('\n') })} rows={3} /></label>}{block.type === 'button' && <div className="inline-fields"><label>Label<input value={block.label || ''} onChange={event => updateBlock(index, { label: event.target.value })} /></label><label>URL<input value={block.url || ''} onChange={event => updateBlock(index, { url: event.target.value })} /></label></div>}{block.type === 'image' && <div className="inline-fields"><label>Image<select value={block.asset_id || ''} onChange={event => updateBlock(index, { asset_id: event.target.value })}><option value="">Choose image</option>{assets.filter(asset => asset.kind === 'image').map(asset => <option key={asset.id} value={asset.id}>{asset.filename}</option>)}</select></label><label>Alt text<input value={block.alt || ''} onChange={event => updateBlock(index, { alt: event.target.value })} /></label></div>}{block.type === 'conditional' && <label>Audience segment<select value={block.condition?.segment_id || ''} onChange={event => updateBlock(index, { condition: { segment_id: event.target.value } })}><option value="">Choose segment</option>{segments.map(segment => <option key={segment.id} value={segment.id}>{segment.name}</option>)}</select></label>}</article>)}</div><div className="button-row"><select aria-label="Add message block" defaultValue="" onChange={event => { if (event.target.value) { addBlock(event.target.value); event.target.value = '' } }}><option value="">+ Add block</option><option value="text">Paragraph</option><option value="heading">Heading</option><option value="list">List</option><option value="button">Button</option><option value="image">Image</option><option value="divider">Divider</option><option value="spacer">Spacing</option><option value="conditional">Conditional</option></select><button onClick={save}>Save draft</button><button onClick={publish}>Publish revision</button></div><div className="studio-preview-controls"><select aria-label="Preview recipient" value={contactId} onChange={event => setContactId(event.target.value)}><option value="">Synthetic sample</option>{contacts.map(contact => <option key={contact.id} value={contact.id}>{contact.normalized_email}</option>)}</select><button className="primary" onClick={renderPreview}>Preview canonical output</button></div>{preview && <div className="studio-preview"><div className="panel-head"><div><h3>{preview.subject}</h3><p className="muted">{preview.approximate_bytes} bytes · {preview.attachments?.length || 0} assets</p></div></div><iframe title="Isolated message preview" sandbox="" srcDoc={preview.html} /><details><summary>Plain text and warnings</summary><pre>{preview.text}</pre>{preview.warnings?.length > 0 && <p className="warning-copy">{preview.warnings.join(' · ')}</p>}</details></div>}</section> : <section className="panel"><Empty text="Select a message or create a new draft to open the studio." /></section>}</div></div>
}


type WorkflowNode = { id: string, kind: string, label: string, config: ApiRecord }
type WorkflowEdge = { source: string, target: string, branch?: string }

const nodeDefaults: Record<string, WorkflowNode> = {
  CONDITION: { id: '', kind: 'CONDITION', label: 'Check whether…', config: { result: true } },
  WAIT: { id: '', kind: 'WAIT', label: 'Wait until…', config: { seconds: 60, timezone: 'UTC', catch_up_policy: 'run_once' } },
  ADD_TO_LIST: { id: '', kind: 'ADD_TO_LIST', label: 'Add to list', config: { list_id: '' } },
  REMOVE_FROM_LIST: { id: '', kind: 'REMOVE_FROM_LIST', label: 'Remove from list', config: { list_id: '' } },
  PREPARE_CAMPAIGN: { id: '', kind: 'PREPARE_CAMPAIGN', label: 'Prepare synthetic campaign', config: { campaign_id: '' } },
  RUN_DATA_STUDIO: { id: '', kind: 'RUN_DATA_STUDIO', label: 'Run Data Studio recipe', config: { recipe_revision_id: '', source_job_id: '', source_artifact_id: '', destination: 'artifact' } },
  NOTE: { id: '', kind: 'NOTE', label: 'Record operator note', config: { note: '' } },
  END: { id: '', kind: 'END', label: 'End', config: {} },
}

function Automations({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [name, setName] = useState('New local automation')
  const [selected, setSelected] = useState('')
  const [detail, setDetail] = useState<ApiRecord | null>(null)
  const [graph, setGraph] = useState<ApiRecord>({ nodes: [], edges: [] })
  const [lists, setLists] = useState<ApiRecord[]>([])
  const [segments, setSegments] = useState<ApiRecord[]>([])
  const [campaigns, setCampaigns] = useState<ApiRecord[]>([])
  const [contacts, setContacts] = useState<ApiRecord[]>([])
  const [dataRecipes, setDataRecipes] = useState<ApiRecord[]>([])
  const [dataJobs, setDataJobs] = useState<ApiRecord[]>([])
  const [dataArtifacts, setDataArtifacts] = useState<Record<string, ApiRecord[]>>({})
  const [contactId, setContactId] = useState('')
  const [runs, setRuns] = useState<ApiRecord[]>([])
  const items: ApiRecord[] = data.items || []

  const refresh = async (id = selected) => {
    if (!id) return
    const next = await api<ApiRecord>(`/automations/${id}`)
    setDetail(next)
    setGraph(next.draft?.graph || next.active?.graph || { nodes: [], edges: [] })
    const runResult = await api<ApiRecord>(`/automations/${id}/runs`)
    setRuns(runResult.items || [])
  }

  useEffect(() => {
    void api<ApiRecord>('/lists').then(result => setLists(result.items || []))
    void api<ApiRecord>('/segments').then(result => setSegments(result.items || []))
    void api<ApiRecord>('/campaigns').then(result => setCampaigns(result.items || []))
    void api<ApiRecord>('/contacts').then(result => setContacts(result.items || []))
    void api<ApiRecord>('/data-studio/recipes').then(result => setDataRecipes(result.items || []))
    void api<ApiRecord>('/data-studio/jobs?limit=100').then(result => setDataJobs(result.items || []))
  }, [])
  useEffect(() => { if (selected) void refresh(selected) }, [selected])

  const nodes: WorkflowNode[] = graph.nodes || []
  const edges: WorkflowEdge[] = graph.edges || []
  const updateNode = (id: string, changes: Partial<WorkflowNode>) => setGraph((current: ApiRecord) => ({
    ...current,
    nodes: (current.nodes || []).map((node: WorkflowNode) => node.id === id ? { ...node, ...changes } : node),
  }))
  const addNode = (kind: string) => {
    const template = nodeDefaults[kind]
    const id = `${kind.toLowerCase()}_${Date.now()}`
    setGraph((current: ApiRecord) => ({
      ...current,
      nodes: [...(current.nodes || []), { ...template, id, config: { ...template.config } }],
    }))
  }
  const removeNode = (id: string) => {
    if (id === 'trigger' || id === 'end') return
    setGraph((current: ApiRecord) => ({
      ...current,
      nodes: current.nodes.filter((node: WorkflowNode) => node.id !== id),
      edges: current.edges.filter((edge: WorkflowEdge) => edge.source !== id && edge.target !== id),
    }))
  }
  const loadDataArtifacts = async (jobId: string) => {
    if (!jobId || dataArtifacts[jobId]) return
    const result = await api<ApiRecord>(`/data-studio/jobs/${jobId}`)
    setDataArtifacts(current => ({ ...current, [jobId]: result.artifacts || [] }))
  }
  const create = () => onRun(async () => {
    const created = await api<ApiRecord>('/automations', { method: 'POST', body: JSON.stringify({ name }) })
    setSelected(created.id)
    await api(`/automations/${created.id}/revisions`, { method: 'POST', body: JSON.stringify({ graph: created.draft.graph }) })
  }, 'Automation created')
  const save = () => selected && onRun(
    () => api(`/automations/${selected}/revisions`, {
      method: 'POST',
      body: JSON.stringify({ graph, revision_id: detail?.draft?.id }),
    }).then(() => refresh(selected)),
    'Draft saved',
  )
  const action = (path: string, message: string) => selected && onRun(
    () => api(`/automations/${selected}/${path}`, {
      method: 'POST',
      body: JSON.stringify({ revision_id: detail?.draft?.id }),
    }).then(() => refresh(selected)),
    message,
  )
  const enroll = () => selected && contactId && onRun(
    () => api(`/automations/${selected}/enroll`, {
      method: 'POST',
      body: JSON.stringify({ contact_id: contactId, event_kind: 'manual_enrollment', provenance: { ui: 'automation-console' } }),
    }).then(() => refresh(selected)),
    'Synthetic contact enrolled',
  )
  const connect = (source: string, target: string | undefined, branch: string) => setGraph((current: ApiRecord) => ({
    ...current,
    edges: [
      ...(current.edges as WorkflowEdge[]).filter(edge => !(edge.source === source && edge.branch === branch)),
      ...(target ? [{ source, target, branch }] : []),
    ],
  }))

  return <div className="content">
    <div className="toolbar"><div><p className="eyebrow teal">VISUAL WORKFLOWS</p><p className="muted">Compose accountable local automation. Every run is synthetic and revision-pinned.</p></div><div className="toolbar-actions"><input aria-label="Automation name" value={name} onChange={event => setName(event.target.value)} /><button className="primary" onClick={create}>+ New automation</button></div></div>
    <div className="automation-layout">
      <section className="panel"><div className="panel-head"><div><h3>Automation library</h3><p className="muted">Draft, active, paused, and archived definitions.</p></div><span className="count-badge">{items.length}</span></div>
        {items.length ? <div className="list-stack">{items.map(item => <button className={item.id === selected ? 'list-row selected' : 'list-row'} key={item.id} onClick={() => setSelected(item.id)}><span><strong>{item.name}</strong><small>{item.status} · {item.active_revision_id ? 'published revision' : 'draft only'}</small></span><b>Open →</b></button>)}</div> : <Empty text="Create a workflow to start mapping an operator journey." />}
      </section>
      {selected && detail ? <section className="panel automation-editor">
        <div className="panel-head"><div><h3>{detail.name}</h3><p className="muted">{detail.status} · draft revision {detail.draft?.revision_number || '—'}</p></div><span className="status-chip">{detail.status}</span></div>
        <div className="workflow-steps" aria-label="Workflow canvas"><p className="eyebrow">WHEN THIS HAPPENS… CHECK WHETHER… WAIT UNTIL… THEN DO… OTHERWISE… END</p>
          {nodes.map(node => <div className={`workflow-node ${node.kind.toLowerCase()}`} key={node.id}>
            <div className="workflow-node-top"><strong>{node.label}</strong><span className="tag">{node.kind}</span>{!['TRIGGER', 'END'].includes(node.kind) && <button className="icon-button" aria-label={`Remove ${node.label}`} onClick={() => removeNode(node.id)}>×</button>}</div>
            {node.kind === 'TRIGGER' && <label>Trigger<select value={node.config.trigger_kind || ''} onChange={event => updateNode(node.id, { config: { ...node.config, trigger_kind: event.target.value } })}><option value="manual_enrollment">Manual enrollment</option><option value="contact_imported">Contact imported</option><option value="contact_added_to_list">Contact added to list</option><option value="scheduled_occurrence">Scheduled occurrence</option><option value="trusted_inbound_event">Trusted inbound event</option></select></label>}
            {node.kind === 'TRIGGER' && node.config.trigger_kind === 'contact_added_to_list' && <label>Trigger list<select value={node.config.list_id || ''} onChange={event => updateNode(node.id, { config: { ...node.config, list_id: event.target.value } })}><option value="">Choose a list</option>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label>}
            {node.kind === 'CONDITION' && <><label>Saved segment (optional)<select value={node.config.segment_id || ''} onChange={event => { const segment = segments.find(item => item.id === event.target.value); updateNode(node.id, { config: { ...node.config, segment_id: event.target.value || undefined, segment_revision_id: segment?.current_revision_id, result: event.target.value ? undefined : true } }) }}><option value="">Static result</option>{segments.map(segment => <option key={segment.id} value={segment.id}>{segment.name} · pinned {segment.current_revision_id?.slice(0, 8)}</option>)}</select></label>{!node.config.segment_id && <label>Condition result<select value={String(node.config.result)} onChange={event => updateNode(node.id, { config: { ...node.config, result: event.target.value === 'true' ? true : event.target.value === 'false' ? false : undefined } })}><option value="true">TRUE</option><option value="false">FALSE</option><option value="unknown">UNKNOWN (safe false)</option></select></label>}</>}
            {node.kind === 'WAIT' && <label>Wait seconds<input type="number" min="0" max="604800" value={node.config.seconds || 0} onChange={event => updateNode(node.id, { config: { ...node.config, seconds: Number(event.target.value) } })} /></label>}
            {['ADD_TO_LIST', 'REMOVE_FROM_LIST'].includes(node.kind) && <label>Static list<select value={node.config.list_id || ''} onChange={event => updateNode(node.id, { config: { ...node.config, list_id: event.target.value } })}><option value="">Choose a list</option>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label>}
            {node.kind === 'PREPARE_CAMPAIGN' && <label>Synthetic campaign<select value={node.config.campaign_id || ''} onChange={event => updateNode(node.id, { config: { ...node.config, campaign_id: event.target.value } })}><option value="">Choose a campaign</option>{campaigns.map(campaign => <option key={campaign.id} value={campaign.id}>{campaign.name} · {campaign.status}</option>)}</select></label>}
            {node.kind === 'RUN_DATA_STUDIO' && <><label>Data Studio recipe revision<select value={node.config.recipe_revision_id || ''} onChange={event => updateNode(node.id, { config: { ...node.config, recipe_revision_id: event.target.value } })}><option value="">Choose a pinned revision</option>{dataRecipes.map(recipe => <option key={recipe.current_revision_id} value={recipe.current_revision_id}>{recipe.name} · {recipe.current_revision_id?.slice(0, 8)}</option>)}</select></label><label>Source job<select value={node.config.source_job_id || ''} onChange={event => { updateNode(node.id, { config: { ...node.config, source_job_id: event.target.value, source_artifact_id: '' } }); void loadDataArtifacts(event.target.value) }}><option value="">Choose a completed job</option>{dataJobs.filter(job => job.status === 'completed').map(job => <option key={job.id} value={job.id}>{job.source_filename} · {job.id.slice(0, 8)}</option>)}</select></label><label>Source artifact<select value={node.config.source_artifact_id || ''} onChange={event => updateNode(node.id, { config: { ...node.config, source_artifact_id: event.target.value } })}><option value="">Choose an artifact</option>{(dataArtifacts[node.config.source_job_id] || []).filter(artifact => artifact.kind === 'output').map(artifact => <option key={artifact.id} value={artifact.id}>{artifact.filename} · {artifact.id.slice(0, 8)}</option>)}</select></label></>}
            {node.kind === 'NOTE' && <label>Operator note<input value={node.config.note || ''} onChange={event => updateNode(node.id, { config: { ...node.config, note: event.target.value } })} /></label>}
          </div>)}
        </div>
        <div className="button-row"><select aria-label="Add workflow node" defaultValue="" onChange={event => { if (event.target.value) { addNode(event.target.value); event.target.value = '' } }}><option value="">+ Add node</option><option value="CONDITION">Check condition</option><option value="WAIT">Wait</option><option value="ADD_TO_LIST">Add to list</option><option value="REMOVE_FROM_LIST">Remove from list</option><option value="PREPARE_CAMPAIGN">Prepare synthetic campaign</option><option value="RUN_DATA_STUDIO">Run Data Studio recipe</option><option value="NOTE">Record note</option><option value="END">End</option></select><button onClick={save}>Save draft</button><button onClick={() => action('validate', 'Workflow validated')}>Validate</button><button onClick={() => action('publish', 'Revision published')}>Publish</button><button className="primary" onClick={() => action('activate', 'Workflow activated')}>Activate</button><button onClick={() => action('pause', 'Workflow paused')}>Pause</button></div>
        <div className="edge-editor"><div className="panel-head"><h3>Connections</h3><span className="muted">Keyboard-accessible edge editor</span></div>
          {nodes.map(node => { const outgoing = edges.filter(edge => edge.source === node.id); return <div className="edge-row" key={'edges-' + node.id}><strong>{node.label}</strong>{node.kind === 'CONDITION' ? ['true', 'false'].map(branch => <label key={branch}>{branch.toUpperCase()}<select aria-label={branch + ' connection from ' + node.label} value={outgoing.find(edge => edge.branch === branch)?.target || ''} onChange={event => connect(node.id, event.target.value || undefined, branch)}><option value="">Choose next node</option>{nodes.filter(target => target.id !== node.id).map(target => <option key={target.id} value={target.id}>{target.label}</option>)}</select></label>) : <select aria-label={'Connection from ' + node.label} value={outgoing.find(edge => edge.branch === 'default')?.target || ''} onChange={event => connect(node.id, event.target.value || undefined, 'default')}><option value="">Choose next node</option>{nodes.filter(target => target.id !== node.id).map(target => <option key={target.id} value={target.id}>{target.label}</option>)}</select>}</div>})}
          {edges.length > 0 && <p className="muted">{edges.length} explicit connections · {edges.map(edge => edge.source + ' → ' + edge.target + ' (' + (edge.branch || 'default') + ')').join(' · ')}</p>}
        </div>
        <div className="enrollment-box"><div><h3>Run a synthetic enrollment</h3><p className="muted">The active published revision is pinned to each run.</p></div><select aria-label="Contact to enroll" value={contactId} onChange={event => setContactId(event.target.value)}><option value="">Choose contact</option>{contacts.map(contact => <option key={contact.id} value={contact.id}>{contact.normalized_email}</option>)}</select><button className="primary" disabled={!contactId || detail.status !== 'active'} onClick={enroll}>Enroll contact</button></div>
        <div className="run-history"><div className="panel-head"><h3>Run history</h3><span className="muted">Durable step diagnostics</span></div>{runs.length ? runs.map(run => <div className="run-row" key={run.id}><span><strong>{run.status}</strong><small>{run.current_node_key} · revision {run.revision_id.slice(0, 8)}</small></span><div className="button-row"><button onClick={() => onRun(() => api(`/automations/runs/${run.id}/advance`, { method: 'POST' }).then(() => refresh(selected)), 'Run advanced')}>Advance</button><button onClick={() => onRun(() => api(`/automations/runs/${run.id}`, { method: 'GET' }), 'Run diagnostics loaded')}>Details</button><button onClick={() => onRun(() => api(`/automations/runs/${run.id}/${run.status === 'paused' ? 'resume' : 'pause'}`, { method: 'POST' }).then(() => refresh(selected)), run.status === 'paused' ? 'Run resumed' : 'Run paused')}>{run.status === 'paused' ? 'Resume' : 'Pause'}</button><button onClick={() => onRun(() => api(`/automations/runs/${run.id}/cancel`, { method: 'POST' }).then(() => refresh(selected)), 'Run canceled')}>Cancel</button></div></div>) : <Empty text="No enrollments yet." />}</div>
      </section> : <section className="panel"><Empty text="Select an automation or create one to open the workflow canvas." /></section>}
    </div>
  </div>
}

function ListTools({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [file, setFile] = useState<File | null>(null)
  const [profile, setProfile] = useState('full')
  const [job, setJob] = useState<ApiRecord | null>(null)
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const jobs: ApiRecord[] = data.items || []
  const refresh = async (id: string) => setJob(await api<ApiRecord>(`/list-tools/jobs/${id}`))
  useEffect(() => { if (!job || ['completed', 'failed', 'canceled', 'paused'].includes(job.status)) return; const timer = window.setInterval(() => void refresh(job.id), 750); return () => window.clearInterval(timer) }, [job])
  const inspect = async () => { if (file) setPreview(await upload('/list-tools/preview', file)) }
  const create = async () => { if (!file) return; const created = await upload('/list-tools/jobs', file, `?profile=${encodeURIComponent(profile)}&dns_mode=offline`); setJob(created); await refresh(created.id) }
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">LIST TOOLS</p><h2>Organize by Provider</h2><p className="muted">Process a local TXT, CSV, JSON, or JSONL file without importing contacts or contacting a provider.</p></div><span className="status-chip">Offline evidence</span></div>
    <section className="panel"><div className="panel-head"><div><h3>Prepare a bounded local job</h3><p className="muted">Preview first, then choose a deterministic classification profile.</p></div></div><label className="file-drop">{file ? file.name : 'Choose a list file'}<input aria-label="List Tools input file" type="file" accept=".txt,.csv,.json,.jsonl" onChange={event => setFile(event.target.files?.[0] || null)} /></label><div className="button-row"><label>Profile<select value={profile} onChange={event => setProfile(event.target.value)}><option value="full">Full classification</option><option value="validation">Validation only</option><option value="dedupe">Dedupe</option><option value="classify">Classify</option></select></label><button disabled={!file} onClick={() => void onRun(inspect, 'Preview calculated without creating contacts')}>Preview</button><button className="primary" disabled={!file} onClick={() => void onRun(create, 'List Tools job started')}>Start processing</button></div>{preview && <div className="stat-grid"><Stat label="Accepted" value={preview.accepted} tone="teal" /><Stat label="Invalid" value={preview.invalid} tone="amber" /><Stat label="Duplicates" value={preview.duplicates} /></div>}</section>
    {job && <section className="panel"><div className="panel-head"><div><h3>Job {job.id.slice(0, 8)}</h3><p className="muted">{job.source_filename} · {job.status} · no Contacts side effect</p></div><span className={`status ${job.status}`}>{job.status}</span></div><p className="muted">Processed {job.processed_count} · accepted {job.accepted_count}</p>{job.summary?.counts && <div className="stat-grid"><Stat label="Invalid" value={job.summary.counts.invalid ?? 0} tone="amber" /><Stat label="Duplicates" value={job.summary.counts.duplicates_removed ?? 0} /><Stat label="Role" value={job.summary.counts.role_based ?? 0} /><Stat label="Disposable" value={job.summary.counts.disposable ?? 0} /></div>}{job.summary?.providers && <p className="muted">Provider groups: {Object.entries(job.summary.providers).map(([name, count]) => `${name} ${count}`).join(' · ')}</p>}<div className="button-row"><button onClick={() => onRun(() => api(`/list-tools/jobs/${job.id}/pause`, { method: 'POST' }).then(() => refresh(job.id)), 'List Tools job paused')}>Pause</button><button onClick={() => onRun(() => api(`/list-tools/jobs/${job.id}/resume`, { method: 'POST' }).then(() => refresh(job.id)), 'List Tools job resumed')}>Resume</button><button onClick={() => onRun(() => api(`/list-tools/jobs/${job.id}/cancel`, { method: 'POST' }).then(() => refresh(job.id)), 'List Tools job canceled')}>Cancel</button></div>{job.artifacts?.length ? <div className="list-stack">{job.artifacts.map((artifact: ApiRecord) => <a className="list-row" key={artifact.id} href={`/api/v1/list-tools/jobs/${job.id}/artifacts/${artifact.id}`}><span><strong>{artifact.filename}</strong><small>{artifact.kind} · {artifact.size_bytes} bytes</small></span><b>Download ↓</b></a>)}</div> : <p className="muted">Artifacts appear when processing completes.</p>}{job.error_message && <div className="error" role="alert">{job.error_message}</div>}</section>}
    <section className="panel table-panel"><div className="panel-head"><h3>Recent jobs</h3><span className="muted">Durable local history</span></div>{jobs.length ? <table><thead><tr><th>Input</th><th>Status</th><th>Accepted</th><th>Updated</th></tr></thead><tbody>{jobs.map(item => <tr key={item.id} onClick={() => void refresh(item.id)}><td><strong>{item.source_filename}</strong><small className="table-subline">{item.profile}</small></td><td>{item.status}</td><td>{item.accepted_count}</td><td>{new Date(item.updated_at).toLocaleString()}</td></tr>)}</tbody></table> : <Empty text="No List Tools jobs yet." />}</section>
  </div>
}

type SegmentRule = { fieldId: string, operator: string, value: string }

const fieldTypes: Record<string, string> = { 'contact.email': 'TEXT', 'contact.display_name': 'TEXT' }
const operatorsByType: Record<string, string[]> = {
  TEXT: ['EQUALS', 'NOT_EQUALS', 'CONTAINS', 'STARTS_WITH', 'ENDS_WITH', 'IS_PRESENT', 'IS_MISSING'],
  NUMBER: ['EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 'GREATER_THAN_OR_EQUAL', 'LESS_THAN_OR_EQUAL', 'IS_PRESENT', 'IS_MISSING'],
  BOOLEAN: ['EQUALS', 'NOT_EQUALS', 'IS_PRESENT', 'IS_MISSING'],
  DATE: ['EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 'IS_PRESENT', 'IS_MISSING'],
  DATETIME: ['EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 'IS_PRESENT', 'IS_MISSING'],
}

function Segments({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [name, setName] = useState('New dynamic audience')
  const [logic, setLogic] = useState('ALL')
  const [nested, setNested] = useState(false)
  const [nestedLogic, setNestedLogic] = useState('ALL')
  const [negate, setNegate] = useState(false)
  const [rules, setRules] = useState<SegmentRule[]>([{ fieldId: 'contact.email', operator: 'EQUALS', value: '' }])
  const [fields, setFields] = useState<ApiRecord[]>([])
  const [preview, setPreview] = useState<ApiRecord | null>(null)
  const [machineKey, setMachineKey] = useState('')
  const [fieldLabel, setFieldLabel] = useState('')
  const [fieldType, setFieldType] = useState('TEXT')
  const refreshFields = () => api('/fields').then(result => setFields(result.items || []))
  useEffect(() => { void refreshFields() }, [])
  const items: ApiRecord[] = data.items || []
  const fieldTypeFor = (fieldId: string) => fields.find(field => field.id === fieldId)?.field_type || fieldTypes[fieldId] || 'TEXT'
  const updateRule = (index: number, changes: Partial<SegmentRule>) => setRules(current => current.map((rule, position) => position === index ? { ...rule, ...changes } : rule))
  const predicates = rules.map(rule => ({ kind: 'PREDICATE', field_id: rule.fieldId, operator: rule.operator, ...( ['IS_PRESENT', 'IS_MISSING'].includes(rule.operator) ? {} : { value: rule.value }) }))
  const group = { kind: logic, children: nested ? [{ kind: nestedLogic, children: predicates }] : predicates }
  const definition = { version: 1, root: negate ? { kind: 'NOT', child: group } : group }
  return <div className="content"><div className="toolbar"><div><p className="eyebrow teal">AUDIENCE LOGIC</p><p className="muted">Build a reusable dynamic audience. Matching is evaluated by the local Python authority.</p></div><span className="status-chip">{items.length} segments</span></div><div className="split"><section className="panel"><div className="panel-head"><h3>New segment</h3><span className="tag">revisioned</span></div><label>Segment name<input value={name} onChange={event => setName(event.target.value)} /></label><label>Combine conditions<select value={logic} onChange={event => setLogic(event.target.value)}><option value="ALL">All conditions (AND)</option><option value="ANY">Any condition (OR)</option></select></label><label><input type="checkbox" checked={nested} onChange={event => setNested(event.target.checked)} /> Nest conditions in a group</label>{nested && <label>Nested group logic<select value={nestedLogic} onChange={event => setNestedLogic(event.target.value)}><option value="ALL">All nested conditions (AND)</option><option value="ANY">Any nested condition (OR)</option></select></label>}<label><input type="checkbox" checked={negate} onChange={event => setNegate(event.target.checked)} /> Negate this group (NOT)</label>{rules.map((rule, index) => { const type = fieldTypeFor(rule.fieldId); const options = operatorsByType[type] || operatorsByType.TEXT; return <div className="rule-row" key={index}><label>Field<select value={rule.fieldId} onChange={event => { const nextType = fieldTypeFor(event.target.value); updateRule(index, { fieldId: event.target.value, operator: operatorsByType[nextType][0], value: '' }) }}><option value="contact.email">Email</option><option value="contact.display_name">Display name</option>{fields.map(field => <option key={field.id} value={field.id}>{field.label}</option>)}</select></label><label>Operator<select value={rule.operator} onChange={event => updateRule(index, { operator: event.target.value, value: '' })}>{options.map(option => <option key={option}>{option}</option>)}</select></label>{!['IS_PRESENT', 'IS_MISSING'].includes(rule.operator) && <label>Value<input type={type === 'NUMBER' ? 'number' : type === 'DATE' ? 'date' : 'text'} value={rule.value} onChange={event => updateRule(index, { value: event.target.value })} /></label>}{rules.length > 1 && <button className="icon-button" aria-label={`Remove condition ${index + 1}`} onClick={() => setRules(current => current.filter((_, position) => position !== index))}>×</button>}</div> })}<div className="button-row"><button onClick={() => setRules(current => [...current, { fieldId: 'contact.email', operator: 'EQUALS', value: '' }])} disabled={rules.length >= 5}>+ Condition</button><button className="primary" disabled={!name || rules.some(rule => !['IS_PRESENT', 'IS_MISSING'].includes(rule.operator) && !rule.value)} onClick={() => onRun(async () => { await api('/segments', { method: 'POST', body: JSON.stringify({ name, definition }) }) }, 'Segment saved')}>Save segment</button></div><details><summary>Create typed field</summary><div className="button-row"><input aria-label="Machine key" placeholder="machine_key" value={machineKey} onChange={event => setMachineKey(event.target.value)} /><input aria-label="Field label" placeholder="Field label" value={fieldLabel} onChange={event => setFieldLabel(event.target.value)} /><select aria-label="Field type" value={fieldType} onChange={event => setFieldType(event.target.value)}><option>TEXT</option><option>NUMBER</option><option>BOOLEAN</option><option>DATE</option><option>DATETIME</option></select><button disabled={!machineKey || !fieldLabel} onClick={() => onRun(async () => { await api('/fields', { method: 'POST', body: JSON.stringify({ machine_key: machineKey, label: fieldLabel, field_type: fieldType }) }); setMachineKey(''); setFieldLabel(''); await refreshFields() }, 'Typed field created')}>Create field</button></div></details></section><section className="panel"><div className="panel-head"><div><h3>Saved segments</h3><p className="muted">Edits create immutable revisions.</p></div></div>{items.length ? <div className="list-stack">{items.map(item => <button className="list-row" key={item.id} onClick={() => onRun(async () => setPreview(await api(`/segments/${item.id}/preview`)), 'Preview loaded')}><span><strong>{item.name}</strong><small>{item.description || 'Dynamic audience'}</small></span><b>Preview →</b></button>)}</div> : <Empty text="Create a segment to preview dynamic membership." />}{preview && <div className="preview-box"><strong>{preview.matched_count} matching contacts</strong><span>Revision {preview.revision_number} · {preview.definition_hash?.slice(0, 12)}</span></div>}</section></div></div>
}

function Contacts({ data: _data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) { const [name, setName] = useState('New audience'); const [listId, setListId] = useState(''); const [file, setFile] = useState<File | null>(null); const [preview, setPreview] = useState<ApiRecord | null>(null); const [lists, setLists] = useState<ApiRecord[]>([]); useEffect(() => { api('/lists').then(r => setLists(r.items || [])) }, []);
  return <div className="content"><div className="toolbar"><div><p className="eyebrow">AUDIENCE WORKBENCH</p><p className="muted">Import, inspect, and keep source provenance close to the record.</p></div><div className="toolbar-actions"><input aria-label="List name" value={name} onChange={e => setName(e.target.value)} /><button className="primary" onClick={() => onRun(async () => { await api('/lists', { method: 'POST', body: JSON.stringify({ name }) }); setLists((await api('/lists')).items || []) }, 'List created')}>+ New list</button></div></div><div className="split"><section className="panel"><div className="panel-head"><h3>Lists</h3><span className="count-badge">{lists.length}</span></div>{lists.length ? <div className="list-stack">{lists.map(list => <button className={list.id === listId ? 'list-row selected' : 'list-row'} key={list.id} onClick={() => setListId(list.id)}><span><strong>{list.name}</strong><small>{list.description || 'No description'}</small></span><b>{list.contact_count} <small>contacts</small></b></button>)}</div> : <Empty text="Create your first audience list." />}</section><section className="panel"><div className="panel-head"><div><h3>Import contacts</h3><p className="muted">CSV, JSONL, JSON, or plain text · 16 MiB cap</p></div></div><label className="file-drop">{file ? file.name : 'Choose a local file'}<input type="file" onChange={e => setFile(e.target.files?.[0] || null)} /></label><div className="button-row"><button disabled={!file} onClick={() => file && onRun(async () => setPreview(await upload('/imports/preview', file)), 'Preview ready')}>Preview</button><button className="primary" disabled={!file || !listId} onClick={() => file && onRun(() => upload('/imports', file, `?list_id=${encodeURIComponent(listId)}`), 'Contacts imported')}>Import to selected list</button></div>{preview && <div className="preview-box"><strong>{preview.accepted} accepted</strong><span>{preview.duplicates} duplicates · {preview.invalid} invalid</span></div>}</section></div><div className="split">{listId ? <StructuredImportPanel listId={listId} onRun={onRun} /> : <section className="panel"><Empty text="Choose a list to validate a structured import." /></section>}{listId && <MembershipHistory listId={listId} />}</div><section className="panel table-panel"><div className="panel-head"><h3>Contact records</h3><span className="muted">Select a list to inspect it.</span></div>{listId ? <ContactTable listId={listId} /> : <Empty text="Choose a list to inspect contacts." />}</section></div> }
function ContactTable({ listId }: { listId: string }) { const [items, setItems] = useState<ApiRecord[]>([]); useEffect(() => { api(`/contacts?list_id=${listId}`).then(r => setItems(r.items || [])) }, [listId]); return items.length ? <table><thead><tr><th>Email</th><th>Display name</th><th>State</th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td>{item.normalized_email}</td><td>{item.display_name || '—'}</td><td><span className="tag">Active</span></td></tr>)}</tbody></table> : <Empty text="No contacts in this list yet." /> }

function StructuredImportPanel({ listId, onRun }: { listId: string, onRun: (action: () => Promise<unknown>, message: string) => void }) { const [rows, setRows] = useState('[{"email":"person@example.com","plan":"pro"}]'); const [mappings, setMappings] = useState('{"email":"contact.email"}'); const [result, setResult] = useState<ApiRecord | null>(null); const request = () => { const body = { list_id: listId, rows: JSON.parse(rows), mappings: JSON.parse(mappings) }; return api('/imports/structured/preview', { method: 'POST', body: JSON.stringify(body) }).then(setResult) }; return <section className="panel"><div className="panel-head"><div><h3>Structured import</h3><p className="muted">Map JSON columns to registered typed fields before writing.</p></div></div><label>Rows (JSON array)<textarea value={rows} onChange={event => setRows(event.target.value)} rows={4} /></label><label>Mappings (JSON object)<textarea value={mappings} onChange={event => setMappings(event.target.value)} rows={2} /></label><div className="button-row"><button disabled={!listId} onClick={() => onRun(request, 'Structured import preview ready')}>Validate mapping</button><button className="primary" disabled={!listId || !result?.valid} onClick={() => onRun(async () => { await api('/imports/structured', { method: 'POST', body: JSON.stringify({ list_id: listId, rows: JSON.parse(rows), mappings: JSON.parse(mappings) }) }) }, 'Structured contacts imported')}>Import typed rows</button></div>{result && <div className="preview-box"><strong>{result.valid ? 'Ready to import' : 'Validation needs attention'}</strong><span>{result.records} records · {result.invalid?.length || 0} invalid</span></div>}</section> }

function MembershipHistory({ listId }: { listId: string }) { const [items, setItems] = useState<ApiRecord[]>([]); useEffect(() => { api(`/lists/${listId}/history`).then(r => setItems(r.items || [])) }, [listId]); return <section className="panel"><div className="panel-head"><h3>Membership history</h3><span className="muted">Append-only list changes</span></div>{items.length ? <div className="list-stack">{items.slice(0, 8).map(item => <div className="list-row" key={item.id}><span><strong>{item.action}</strong><small>{item.source} · {item.reason}</small></span><code>{item.occurred_at}</code></div>)}</div> : <Empty text="No membership changes recorded yet." />}</section> }

function Campaigns({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [legacySelected, setLegacySelected] = useState(''); const [legacyPreview, setLegacyPreview] = useState<ApiRecord | null>(null)
  const fieldValue = (caption: string) => { const label = Array.from(document.querySelectorAll('label')).find(item => item.textContent?.startsWith(caption)); const control = label?.querySelector('input, textarea, select') as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | null; return control?.value || '' }
  const createLegacy = () => onRun(async () => { const result = await api<ApiRecord>('/campaigns', { method: 'POST', body: JSON.stringify({ name: fieldValue('Campaign name') || 'Synthetic launch', list_id: fieldValue('Audience list') || null, segment_id: fieldValue('Or dynamic segment') || null, sender_email: fieldValue('Sender email') || 'sender@example.com', subject: fieldValue('Subject') || 'A local test message', text: fieldValue('Message text') || 'Hello {{ email }}', purpose: fieldValue('Communication purpose') || 'transactional' }) }); setLegacySelected(result.id) }, 'Campaign created')
  const legacyAction = (path: string, message: string) => onRun(async () => { if (path === '/preview') setLegacyPreview(await api(`/campaigns/${legacySelected}/preview`)); else await api(`/campaigns/${legacySelected}${path}`, { method: 'POST' }) }, message)
  return <><div className="legacy-campaign-actions"><button className="primary" onClick={createLegacy}>Create campaign</button>{legacySelected && <><button onClick={() => legacyAction('/prepare', 'Campaign prepared')}>Prepare</button><button onClick={() => legacyAction('/preview', 'Campaign preview loaded')}>Preview</button><button onClick={() => legacyAction('/authorize', 'Simulation authorized')}>Authorize</button><button className="primary" onClick={() => legacyAction('/simulate', 'Synthetic worker started')}>Run synthetic</button></>}{legacyPreview && <pre className="preview-json">{JSON.stringify(legacyPreview, null, 2)}</pre>}</div><CampaignWorkspace data={data} onRun={onRun} /><CampaignPreviewPanel campaignId={legacySelected || data.items?.[0]?.id} /></>
}

function CampaignPreviewPanel({ campaignId }: { campaignId?: string }) {
  const [previews, setPreviews] = useState<ApiRecord[]>([])
  useEffect(() => { if (campaignId) void api<ApiRecord>(`/campaigns/${campaignId}/workspace`).then(result => setPreviews(result.message_previews || [])).catch(() => setPreviews([])) }, [campaignId])
  if (!campaignId || !previews.length) return null
  return <section className="panel campaign-preview-panel"><div className="panel-head"><div><h3>Message previews</h3><p className="muted">Rendered by the canonical local message authority for synthetic recipients.</p></div><span className="tag">preview only</span></div>{previews.map((preview, index) => <article key={index} className="message-preview-card"><strong>{preview.subject || 'No subject'}</strong><small>{preview.email || `Synthetic recipient ${index + 1}`}</small><p>{preview.text || 'No text preview available.'}</p>{preview.warnings?.length ? <span className="warning-copy">{preview.warnings.join(' · ')}</span> : null}</article>)}</section>
}

function CampaignWorkspace({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [name, setName] = useState('Synthetic launch'); const [description, setDescription] = useState(''); const [listId, setListId] = useState(''); const [segmentId, setSegmentId] = useState(''); const [segmentRevisionId, setSegmentRevisionId] = useState(''); const [segmentRevisions, setSegmentRevisions] = useState<ApiRecord[]>([]); const [subject, setSubject] = useState('A local test message'); const [text, setText] = useState('Hello {{ email }}'); const [email, setEmail] = useState('sender@example.com'); const [messageRevisionId, setMessageRevisionId] = useState(''); const [messages, setMessages] = useState<ApiRecord[]>([]); const [selected, setSelected] = useState(''); const [workspace, setWorkspace] = useState<ApiRecord | null>(null); const [purpose, setPurpose] = useState('transactional'); const [preview, setPreview] = useState<ApiRecord | null>(null); const [lists, setLists] = useState<ApiRecord[]>([]); const [segments, setSegments] = useState<ApiRecord[]>([]); const [accounts, setAccounts] = useState<ApiRecord[]>([]); const [accountRef, setAccountRef] = useState(''); const [scheduleMode, setScheduleMode] = useState('immediate'); const [timezone, setTimezone] = useState('UTC'); const [scheduledAt, setScheduledAt] = useState(''); const [section, setSection] = useState('overview')
  void preview; void setPreview
  useEffect(() => { api('/lists').then(r => setLists(r.items || [])); api('/segments').then(r => setSegments(r.items || [])); api('/providers').then(r => setAccounts(r.items || [])); api('/message-studio/documents').then(r => setMessages((r.items || []).filter((item: ApiRecord) => item.current_published_revision_id))) }, [])
  useEffect(() => { if (segmentId) void api(`/segments/${segmentId}`).then(r => { setSegmentRevisions(r.revisions || []); setSegmentRevisionId(r.revision?.id || '') }).catch(() => { setSegmentRevisions([]); setSegmentRevisionId('') }); else { setSegmentRevisions([]); setSegmentRevisionId('') } }, [segmentId])
  const items = data.items || []; const usingSegment = Boolean(segmentId)
  const loadWorkspace = async (id: string) => { const result = await api<ApiRecord>(`/campaigns/${id}/workspace`); setWorkspace(result); const campaign = result.campaign || {}; setName(campaign.name || ''); setDescription(campaign.description || ''); setPurpose(campaign.configuration?.communication_purpose || 'transactional'); setSubject(campaign.configuration?.subject || ''); setText(campaign.configuration?.text || 'Hello {{ email }}'); setEmail(campaign.configuration?.sender_email || 'sender@example.com'); setAccountRef(campaign.provider_account_ref || ''); setListId(campaign.audience_source_type === 'list' ? campaign.audience_source_id : ''); setSegmentId(campaign.audience_source_type === 'segment' ? campaign.audience_source_id : ''); setSegmentRevisionId(campaign.audience_revision_id || ''); setMessageRevisionId(campaign.message_revision_id || ''); setSelected(id) }
  const action = (id: string, path: string, message: string, body?: object) => onRun(async () => { await api(`/campaigns/${id}${path}`, { method: 'POST', body: body ? JSON.stringify(body) : undefined }); await loadWorkspace(id) }, message)
  const create = () => onRun(async () => { const result = await api<ApiRecord>('/campaigns', { method: 'POST', body: JSON.stringify({ name, description, purpose, list_id: listId || null, segment_id: segmentId || null, segment_revision_id: segmentRevisionId || null, message_revision_id: messageRevisionId || null, provider_account_ref: accountRef || null, sender_email: email, subject, text }) }); await loadWorkspace(result.id) }, 'Campaign draft created')
  const save = () => selected && onRun(async () => { await api(`/campaigns/${selected}`, { method: 'PATCH', body: JSON.stringify({ name, description, purpose, list_id: workspace?.campaign?.audience_source_type === 'list' ? workspace.campaign.audience_source_id : null, segment_id: workspace?.campaign?.audience_source_type === 'segment' ? workspace.campaign.audience_source_id : null, segment_revision_id: workspace?.campaign?.audience_revision_id || null, message_revision_id: messageRevisionId || workspace?.campaign?.message_revision_id || null, provider_account_ref: accountRef || null, sender_email: email, subject, text, expected_updated_at: workspace?.campaign?.updated_at }) }); await loadWorkspace(selected) }, 'Draft saved')
  const schedule = () => selected && onRun(async () => { await api(`/campaigns/${selected}/schedule`, { method: 'PUT', body: JSON.stringify({ mode: scheduleMode, timezone, scheduled_at: scheduledAt || null, weekdays: [0,1,2,3,4,5,6], catch_up_policy: 'skip' }) }); await loadWorkspace(selected) }, 'Schedule saved')
  return <div className="content campaign-workspace"><div className="toolbar"><div><p className="eyebrow">CAMPAIGN OPERATIONS</p><h2>Campaign workspace</h2><p className="muted">Create, review, prepare, and supervise a bounded synthetic run from one durable plan.</p></div><div className="status-chip amber-chip">No network delivery</div></div><div className="campaign-layout"><section className="panel campaign-editor"><div className="panel-head"><div><h3>{selected ? 'Edit campaign draft' : 'New campaign'}</h3><p className="muted">Source choices and published revisions are pinned before execution.</p></div><span className="tag">local authority</span></div><label>Campaign name<input value={name} onChange={e => setName(e.target.value)} /></label><label>Description<input value={description} onChange={e => setDescription(e.target.value)} /></label><label>Communication purpose<select value={purpose} onChange={e => setPurpose(e.target.value)}><option value="transactional">Transactional</option><option value="marketing">Marketing</option><option value="account">Account</option></select></label><label>Audience list<select value={listId} disabled={usingSegment || Boolean(selected)} onChange={e => { setListId(e.target.value); setSegmentId('') }}><option value="">Choose a list</option>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label><label>Or dynamic segment<select value={segmentId} disabled={Boolean(listId) || Boolean(selected)} onChange={e => { setSegmentId(e.target.value); setListId('') }}><option value="">Choose a segment</option>{segments.map(segment => <option key={segment.id} value={segment.id}>{segment.name}</option>)}</select></label>{segmentId && <label>Pin segment revision<select value={segmentRevisionId} onChange={e => setSegmentRevisionId(e.target.value)}>{segmentRevisions.map(revision => <option key={revision.id} value={revision.id}>Revision {revision.revision_number}</option>)}</select></label>}<label>Provider account<select aria-label="Provider account" value={accountRef} onChange={e => setAccountRef(e.target.value)}><option value="">Synthetic account (no external delivery)</option>{accounts.map(account => <option key={account.ref} value={account.ref}>{account.display_name || account.ref} · {account.status}</option>)}</select></label><label>Published message revision<select aria-label="Message revision" value={messageRevisionId || workspace?.campaign?.message_revision_id || ''} onChange={e => setMessageRevisionId(e.target.value)}><option value="">Use campaign text</option>{messages.map(message => <option key={message.current_published_revision_id} value={message.current_published_revision_id}>{message.name} · published</option>)}</select></label><label>Sender email<input value={email} onChange={e => setEmail(e.target.value)} /></label><label>Subject<input value={subject} onChange={e => setSubject(e.target.value)} /></label><label>Message text<textarea rows={5} value={text} onChange={e => setText(e.target.value)} /></label><div className="button-row"><button className="primary" disabled={!listId && !segmentId} onClick={selected ? save : create}>{selected ? 'Save draft' : 'Create draft'}</button>{selected && <button onClick={() => { setSelected(''); setWorkspace(null) }}>New draft</button>}</div></section><section className="panel campaign-queue"><div className="panel-head"><div><h3>Campaign queue</h3><p className="muted">Select a campaign to open its durable workspace.</p></div></div><CampaignTable items={items} empty="No campaigns have been created." onSelect={id => void loadWorkspace(id)} />{workspace && <div className="workspace-card"><div className="panel-head"><div><h3>{workspace.campaign.name}</h3><p className="muted">{workspace.campaign.status} · {workspace.campaign.authorization}</p></div><span className={`status ${workspace.campaign.status}`}>{workspace.campaign.status}</span></div><div className="workspace-grid"><div><span className="eyebrow">AUDIENCE</span><strong>{workspace.audience.status || 'not prepared'}</strong><small>{workspace.campaign.audience_source_type}: {workspace.campaign.audience_source_id}</small></div><div><span className="eyebrow">SENDER</span><strong>{workspace.provider?.display_name || 'Synthetic local sender'}</strong><small>{workspace.provider?.status || 'simulation boundary'}</small></div><div><span className="eyebrow">PROGRESS</span><strong>{workspace.progress.total ?? 0} recipients</strong><small>{workspace.progress.accepted ?? 0} accepted · {workspace.progress.ambiguous ?? 0} ambiguous</small></div></div><div className="workspace-tabs" role="tablist" aria-label="Campaign evidence"><button className={section === 'overview' ? 'active' : ''} onClick={() => setSection('overview')}>Overview</button><button className={section === 'recipients' ? 'active' : ''} onClick={() => { setSection('recipients'); void api(`/campaigns/${selected}/recipients`).then(result => setWorkspace(current => current ? { ...current, recipients: result.items } : current)) }}>Recipients</button><button className={section === 'attempts' ? 'active' : ''} onClick={() => { setSection('attempts'); void api(`/campaigns/${selected}/attempts`).then(result => setWorkspace(current => current ? { ...current, attempts: result.items } : current)) }}>Attempts</button></div>{section === 'overview' && <><div className="preflight-box"><div className="panel-head"><div><h4>Preflight</h4><p className="muted">Current blockers and warnings before preparation.</p></div><span className={workspace.preflight.ready ? 'status completed' : 'status failed'}>{workspace.preflight.ready ? 'ready' : `${workspace.preflight.blocker_count} blockers`}</span></div>{workspace.preflight.findings?.map((finding: ApiRecord) => <div className={`finding ${finding.severity}`} key={`${finding.code}-${finding.message}`}><strong>{finding.code}</strong><span>{finding.message}</span><small>{finding.action || finding.source}</small></div>)}</div><div className="schedule-box"><div className="panel-head"><div><h4>Execution plan</h4><p className="muted">Timezone and pacing stay explicit; all runs remain synthetic.</p></div></div><div className="inline-fields"><label>Mode<select value={scheduleMode} onChange={e => setScheduleMode(e.target.value)}><option value="immediate">Immediate</option><option value="at">At a time</option><option value="window">Window</option></select></label><label>Timezone<input value={timezone} onChange={e => setTimezone(e.target.value)} /></label>{scheduleMode === 'at' && <label>Scheduled local time<input value={scheduledAt} onChange={e => setScheduledAt(e.target.value)} placeholder="2026-11-01T09:00:00" /></label>}</div><button onClick={schedule}>Save schedule</button></div><div className="button-row action-dock"><button onClick={() => action(selected, '/preflight', 'Preflight refreshed')}>Refresh preflight</button><button onClick={() => action(selected, '/prepare', 'Campaign prepared')}>Prepare snapshots</button><button onClick={() => action(selected, '/authorize', 'Synthetic execution authorized')}>Authorize synthetic</button><button className="primary" onClick={() => action(selected, '/simulate', 'Synthetic worker started')}>Start synthetic</button><button onClick={() => action(selected, '/pause', 'Pause requested')}>Pause</button><button onClick={() => action(selected, '/resume', 'Resume requested')}>Resume</button><button onClick={() => { if (window.confirm('Cancel this campaign?')) action(selected, '/cancel', 'Campaign canceled') }}>Cancel</button><a className="button-link" href={`/api/v1/campaigns/${selected}/export?format=csv`}>Export CSV</a></div></>}{section === 'recipients' && <EvidenceTable rows={workspace.recipients || workspace.preview || []} columns={['email', 'state', 'eligibility_reason', 'attempt_count']} />}{section === 'attempts' && <EvidenceTable rows={workspace.attempts || []} columns={['attempt_number', 'attempt_state', 'outcome', 'transport_phase', 'error_code']} />}</div>}</section></div></div>
}
function EvidenceTable({ rows, columns }: { rows: ApiRecord[], columns: string[] }) { return rows.length ? <div className="table-panel evidence-table"><table><thead><tr>{columns.map(column => <th key={column}>{column.replace('_', ' ')}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={row.id || index}>{columns.map(column => <td key={column}>{row[column] ?? '—'}</td>)}</tr>)}</tbody></table></div> : <Empty text="No durable evidence is available for this campaign yet." /> }
function CampaignTable({ items, empty, onSelect }: { items: ApiRecord[], empty: string, onSelect?: (id: string) => void }) { return items.length ? <div className="campaign-list">{items.map(item => <button className="campaign-row" key={item.id} onClick={() => onSelect?.(item.id)}><span className="campaign-icon">↗</span><span className="campaign-main"><strong>{item.name}</strong><small>{item.description || item.template_ref || 'Local campaign'}</small></span><span className={`status ${item.status}`}>{item.status?.replace('_', ' ')}</span><span className="row-arrow">→</span></button>)}</div> : <Empty text={empty} /> }

function Inbound({ data, onRun }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void }) {
  const [reviews, setReviews] = useState<ApiRecord[]>(data.items || []); const [file, setFile] = useState<File | null>(null)
  const [query, setQuery] = useState(''); const [classification, setClassification] = useState(''); const [folder, setFolder] = useState(''); const [read, setRead] = useState(''); const [flagged, setFlagged] = useState('')
  const [messages, setMessages] = useState<ApiRecord[]>(data.messages || []); const [selected, setSelected] = useState<ApiRecord | null>(null)
  const [rules, setRules] = useState<ApiRecord[]>([]); const [ruleName, setRuleName] = useState('Subject review rule')
  const [ruleSubject, setRuleSubject] = useState(''); const [ruleActive, setRuleActive] = useState('')
  const [accounts, setAccounts] = useState<ApiRecord[]>([]); const [accountRef, setAccountRef] = useState('')
  const [mailboxes, setMailboxes] = useState<ApiRecord[]>([]); const [syncAuthorization, setSyncAuthorization] = useState(''); const [syncPurpose, setSyncPurpose] = useState('Local operator sync'); const [targetFolder, setTargetFolder] = useState('Archive'); const [conversation, setConversation] = useState<ApiRecord | null>(null)
  useEffect(() => { setMessages(data.messages || []); setReviews(data.items || []) }, [data.messages, data.items])
  const loadMailboxes = async (ref = accountRef) => { if (!ref) { setMailboxes([]); return }; const result = await api<ApiRecord>(`/providers/${ref}/mailboxes`); setMailboxes(result.items || []) }
  const search = async () => { const params = new URLSearchParams(); if (query) params.set('q', query); if (classification) params.set('classification', classification); if (folder) params.set('folder', folder); if (read) params.set('read', read); if (flagged) params.set('flagged', flagged); const result = await api<ApiRecord>(`/inbound?${params}`); setMessages(result.messages || []) }
  const inspect = async (id: string) => setSelected(await api<ApiRecord>(`/inbound/messages/${id}`))
  const inspectConversation = async (id: string) => setConversation(await api<ApiRecord>(`/inbound/messages/${id}/conversation`))
  const createRule = () => onRun(async () => { const result = await api<ApiRecord>('/inbound/rules', { method: 'POST', body: JSON.stringify({ name: ruleName, definition: { version: 1, conditions: ruleSubject ? [{ field: 'subject', op: 'contains', value: ruleSubject }] : [], actions: [{ type: 'extract', fields: ['sender', 'subject'] }, { type: 'record_event', label: 'Inbound rule matched' }] } }) }); setRules(items => [...items, result]); setRuleActive(result.id) }, 'Inbound rule saved')
  const importEvidence = () => { if (!file) return; const path = file.name.toLowerCase().endsWith('.mbox') ? '/inbound/import-mbox' : '/inbound/import'; onRun(() => upload(path, file), 'Inbound evidence acquired') }
  useEffect(() => { void api<ApiRecord>('/inbound/rules').then(result => setRules(result.items || [])); void api<ApiRecord>('/providers/accounts').then(result => setAccounts(result.items || [])) }, [])
  useEffect(() => { void loadMailboxes() }, [accountRef])
  const sync = () => accountRef && onRun(async () => { const expiry = new Date(Date.now() + 60 * 60 * 1000).toISOString(); await api(`/inbound/mailboxes/${accountRef}/sync`, { method: 'POST', body: JSON.stringify({ mailbox: folder || 'INBOX', batch_limit: 100, retain_raw: true, authorization_ref: syncAuthorization, purpose: syncPurpose, expires_at: expiry }) }); await loadMailboxes() }, 'Inbound mailbox sync completed')
  const discover = () => accountRef && onRun(async () => { const expiry = new Date(Date.now() + 60 * 60 * 1000).toISOString(); await api(`/providers/${accountRef}/mailboxes/discover`, { method: 'POST', body: JSON.stringify({ authorization_ref: syncAuthorization, purpose: syncPurpose, expires_at: expiry }) }); await loadMailboxes() }, 'Mailbox folders discovered')
  const remoteAction = (action: string, target?: string) => { if (!selected?.remote_uid || !selected.remote_uidvalidity || !accountRef) return; return onRun(async () => { const expiry = new Date(Date.now() + 60 * 60 * 1000).toISOString(); await api(`/inbound/mailboxes/${accountRef}/actions?message_id=${encodeURIComponent(selected.id)}`, { method: 'POST', body: JSON.stringify({ action, authorization_ref: syncAuthorization, idempotency_key: `${action}:${selected.id}:${Date.now()}`, target_folder: target || null, uidvalidity: selected.remote_uidvalidity, uid: selected.remote_uid, flags: action === 'flag' || action === 'unflag' ? ['\\Flagged'] : [], purpose: syncPurpose, expires_at: expiry }) }); await inspect(selected.id) }, `Mailbox action ${action} recorded`) }
  return <div className="content"><div className="toolbar"><div><p className="eyebrow">INBOUND WORKBENCH</p><p className="muted">Durable local evidence, safe inspection, and explicit operator actions.</p></div><span className="status-chip">{reviews.length} pending</span></div>
    <section className="panel"><div className="panel-head"><div><h3>Acquire local evidence</h3><p className="muted">EML/MBOX upload · 10 MiB cap · read-only mailbox acquisition</p></div></div><label className="file-drop">{file ? file.name : 'Choose an EML or MBOX file'}<input aria-label="Inbound EML file" type="file" accept=".eml,.mbox,message/rfc822,application/mbox" onChange={e => setFile(e.target.files?.[0] || null)} /></label><button className="primary" disabled={!file} onClick={importEvidence}>Import evidence for review</button></section>
    <section className="panel"><div className="panel-head"><div><h3>Authorized mailbox sync</h3><p className="muted">IMAP stays read-only by default; sync and folder discovery require an explicit authorization reference.</p></div><span className="tag">no automatic fetch</span></div><div className="inline-fields"><label>IMAP account<select aria-label="Inbound mailbox account" value={accountRef} onChange={e => setAccountRef(e.target.value)}><option value="">Choose account</option>{accounts.filter(account => account.kind === 'imap').map(account => <option key={account.ref} value={account.ref}>{account.display_name || account.ref}</option>)}</select></label><label>Folder<select aria-label="Inbound mailbox folder" value={folder} onChange={e => setFolder(e.target.value)}><option value="">INBOX</option>{mailboxes.map(mailbox => <option key={mailbox.mailbox} value={mailbox.mailbox}>{mailbox.mailbox}</option>)}</select></label><label>Authorization reference<input value={syncAuthorization} onChange={e => setSyncAuthorization(e.target.value)} placeholder="owner-approved scope" /></label><label>Purpose<input value={syncPurpose} onChange={e => setSyncPurpose(e.target.value)} /></label><div className="button-row"><button onClick={discover} disabled={!accountRef || !syncAuthorization}>Discover folders</button><button className="primary" disabled={!accountRef || !syncAuthorization} onClick={sync}>Sync folder</button></div></div>{mailboxes.length ? <div className="mailbox-strip">{mailboxes.map(mailbox => <span className="tag" key={mailbox.mailbox}>{mailbox.mailbox} · {mailbox.last_sync_status || 'discovered'}{mailbox.mutation_enabled ? ' · mutations enabled' : ' · read-only'}</span>)}</div> : null}</section>
    <section className="panel"><div className="panel-head"><div><h3>Search and filter</h3><p className="muted">Sender, subject, thread, remote flags, and deterministic classification.</p></div></div><div className="inline-fields"><label>Search<input aria-label="Search inbound messages" value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e => e.key === 'Enter' && void search()} /></label><label>Folder<input aria-label="Filter inbound folder" value={folder} onChange={e => setFolder(e.target.value)} /></label><label>Read<select aria-label="Filter read state" value={read} onChange={e => setRead(e.target.value)}><option value="">Any read state</option><option value="true">Read</option><option value="false">Unread</option></select></label><label>Flagged<select aria-label="Filter flagged state" value={flagged} onChange={e => setFlagged(e.target.value)}><option value="">Any flag state</option><option value="true">Flagged</option><option value="false">Unflagged</option></select></label><label>Classification<select aria-label="Filter inbound classification" value={classification} onChange={e => setClassification(e.target.value)}><option value="">All classifications</option><option value="human_reply">Human reply</option><option value="delivery_status">Delivery status</option><option value="complaint">Complaint</option><option value="unsubscribe">Unsubscribe</option><option value="automatic_reply">Automatic reply</option></select></label><button onClick={() => void search()}>Search</button></div></section>
    <section className="panel table-panel"><div className="panel-head"><h3>Review queue</h3><span className="muted">Policy changes wait for review</span></div>{reviews.length ? reviews.map((review: ApiRecord) => <div className="review-row" key={review.id}><div><strong>{review.action_type}</strong><p>{review.action_reason || review.reason}</p><small>{review.target || 'No target'} · {review.status}</small></div><div className="button-row"><button onClick={() => onRun(async () => { await api(`/inbound/reviews/${review.action_id}`, { method: 'POST', body: JSON.stringify({ decision: 'reject', reason: 'Rejected in local console' }) }); setReviews(items => items.filter(item => item.id !== review.id)) }, 'Review rejected')}>Reject</button><button className="primary" onClick={() => onRun(async () => { await api(`/inbound/reviews/${review.action_id}`, { method: 'POST', body: JSON.stringify({ decision: 'approve', reason: 'Approved in local console' }) }); setReviews(items => items.filter(item => item.id !== review.id)) }, 'Review approved')}>Approve</button></div></div>) : <Empty text="No inbound actions need review." />}</section>
    <section className="panel table-panel"><div className="panel-head"><h3>Messages</h3><span className="muted">{messages.length} shown · click a row to inspect</span></div>{messages.length ? <table><thead><tr><th>Subject</th><th>Folder</th><th>Classification</th><th>Remote state</th></tr></thead><tbody>{messages.map((message: ApiRecord) => { const correlation = message.correlations?.[0] || {}; return <tr key={message.id} tabIndex={0} onClick={() => void inspect(message.id)} onKeyDown={e => e.key === 'Enter' && void inspect(message.id)}><td><strong>{message.subject || 'No subject'}</strong><small className="table-subline">{message.sender || 'Unknown sender'}</small></td><td>{message.folder || 'local evidence'}</td><td>{message.classification || message.parse_status}<small className="table-subline">{correlation.match_kind || 'unmatched'}</small></td><td>{message.remote_state || (message.processed_at ? 'processed' : 'pending')} {message.remote_flags_json ? '· flags observed' : ''}</td></tr> })}</tbody></table> : <Empty text="No inbound evidence acquired yet." />}</section>
    <section className="panel"><div className="panel-head"><div><h3>Rules</h3><p className="muted">Typed, bounded rules; no scripts, SQL, or network actions.</p></div></div><div className="inline-fields"><label>Rule name<input value={ruleName} onChange={e => setRuleName(e.target.value)} /></label><label>Subject contains<input value={ruleSubject} onChange={e => setRuleSubject(e.target.value)} /></label><button className="primary" onClick={createRule}>Save paused rule</button></div>{rules.map(rule => <div className="list-row" key={rule.id}><span><strong>{rule.name}</strong><small>{rule.status} · priority {rule.priority}</small></span><button onClick={() => onRun(() => api(`/inbound/rules/${rule.id}/status`, { method: 'POST', body: JSON.stringify({ status: ruleActive === rule.id ? 'paused' : 'active' }) }), 'Rule status updated')}>{ruleActive === rule.id ? 'Pause' : 'Activate'}</button></div>)}</section>
    {selected && <section className="panel"><div className="panel-head"><div><h3>{selected.subject || 'Inbound message'}</h3><p className="muted">{selected.sender || 'Unknown sender'} · {selected.folder || 'local evidence'} · raw content is not rendered here</p></div><button onClick={() => { setSelected(null); setConversation(null) }}>Close</button></div><p>{selected.text_preview || selected.html_preview || 'No safe text preview available.'}</p><p className="muted">Attachments: {selected.attachments?.length || 0} · Correlations: {selected.correlations?.length || 0} · Remote UID: {selected.remote_uid || 'not available'}</p><div className="button-row"><button onClick={() => onRun(() => api(`/inbound/messages/${selected.id}/extract`, { method: 'POST', body: JSON.stringify({ fields: ['sender', 'recipients', 'subject', 'date'] }) }), 'Message fields extracted')}>Extract fields</button><button onClick={() => inspectConversation(selected.id)}>Open conversation</button><button onClick={() => remoteAction('mark_read')} disabled={!selected.remote_uid}>Mark read</button><button onClick={() => remoteAction('mark_unread')} disabled={!selected.remote_uid}>Mark unread</button><button onClick={() => remoteAction('flag')} disabled={!selected.remote_uid}>Flag</button><button onClick={() => remoteAction('unflag')} disabled={!selected.remote_uid}>Unflag</button><button onClick={() => onRun(() => api(`/inbound/messages/${selected.id}/draft`, { method: 'POST', body: JSON.stringify({ kind: 'reply', body: '' }) }), 'Reply draft prepared in Message Studio')}>Prepare reply draft</button><button onClick={() => onRun(() => api(`/inbound/messages/${selected.id}/draft`, { method: 'POST', body: JSON.stringify({ kind: 'reply_all', body: '' }) }), 'Reply-all draft prepared in Message Studio')}>Prepare reply-all draft</button><button onClick={() => onRun(() => api(`/inbound/messages/${selected.id}/draft`, { method: 'POST', body: JSON.stringify({ kind: 'forward', body: '' }) }), 'Forward draft prepared in Message Studio')}>Prepare forward draft</button></div><div className="inline-fields"><label>Target folder<input aria-label="Mailbox target folder" value={targetFolder} onChange={e => setTargetFolder(e.target.value)} /></label><button onClick={() => remoteAction('copy', targetFolder)} disabled={!selected.remote_uid || !targetFolder}>Copy to folder</button><button onClick={() => remoteAction('move', targetFolder)} disabled={!selected.remote_uid || !targetFolder}>Move to folder</button><button onClick={() => remoteAction('archive', targetFolder)} disabled={!selected.remote_uid || !targetFolder}>Archive</button></div>{conversation && <div className="workspace-card"><div className="panel-head"><div><h4>Conversation</h4><p className="muted">{conversation.confidence} · {conversation.items?.length || 0} messages</p></div></div>{conversation.items?.map((item: ApiRecord) => <p key={item.id}><strong>{item.subject || 'No subject'}</strong> · {item.sender || 'Unknown sender'} · {item.received_at || item.acquired_at}</p>)}</div>}</section>}
  </div>
}
function Providers({ data, onRun, sessionReady }: { data: ApiRecord, onRun: (action: () => Promise<unknown>, message: string) => void, sessionReady: boolean }) {
  const profiles = data.items || []
  const [capabilities, setCapabilities] = useState<ApiRecord[]>([])
  const [preset, setPreset] = useState('generic_smtp')
  const [ref, setRef] = useState('local-smtp')
  const [host, setHost] = useState('127.0.0.1')
  const [port, setPort] = useState('465')
  const [username, setUsername] = useState('operator@example.com')
  const [credentialRef, setCredentialRef] = useState('test:provider')
  const [kind, setKind] = useState('smtp')
  const [authMethod, setAuthMethod] = useState('password')
  const [tlsMode, setTlsMode] = useState('implicit_tls')
  const [selected, setSelected] = useState<ApiRecord | null>(null)
  const [testRef, setTestRef] = useState('')
  const [testSender, setTestSender] = useState('')
  const [testRecipient, setTestRecipient] = useState('')
  const [testMessage, setTestMessage] = useState('Subject: Mailforge qualification test\n\nLocal controlled test message.')
  const newTestKey = () => `test-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
  const [testKey, setTestKey] = useState(newTestKey)
  const [testAuthorization, setTestAuthorization] = useState('')
  const [testPurpose, setTestPurpose] = useState('')
  const [testExpiry, setTestExpiry] = useState(() => new Date(Date.now() + 60 * 60 * 1000).toISOString())
  const [testConfirmed, setTestConfirmed] = useState(false)
  const [grantIssued, setGrantIssued] = useState(false)
  const [inboundRef, setInboundRef] = useState('')
  const [mailbox, setMailbox] = useState('INBOX')
  const [maxFetch, setMaxFetch] = useState('100')
  const [syncEnabled, setSyncEnabled] = useState(false)
  const [mutationEnabled, setMutationEnabled] = useState(false)
  useEffect(() => {
    if (!sessionReady) return
    void api<ApiRecord>('/providers/capabilities')
      .then(result => setCapabilities(result.items || []))
      .catch(() => setCapabilities([]))
  }, [sessionReady])
  const capability = capabilities.find(item => item.key === preset)
  const applyPreset = (nextPreset: string, nextKind = kind) => {
    const next = capabilities.find(item => item.key === nextPreset)
    setPreset(nextPreset)
    if (!next) return
    const supportedKinds = next.protocols || []
    const resolvedKind = supportedKinds.includes(nextKind) ? nextKind : (supportedKinds[0] || nextKind)
    setKind(resolvedKind)
    const defaults = resolvedKind === 'imap' ? next.inbound_defaults : next.outbound_defaults
    if (defaults?.host) setHost(String(defaults.host))
    if (defaults?.port) setPort(String(defaults.port))
    if (defaults?.mailbox) setMailbox(String(defaults.mailbox))
    const methods = next.auth_methods || []
    if (!methods.includes(authMethod)) setAuthMethod(methods[0] || 'password')
    const modes = next.tls_modes || []
    const preferredTls = resolvedKind === 'imap' ? 'implicit_tls' : (modes.includes('starttls') ? 'starttls' : modes[0])
    if (preferredTls) setTlsMode(preferredTls)
  }
  const changeKind = (nextKind: string) => { setKind(nextKind); applyPreset(preset, nextKind) }
  const create = () => onRun(() => api('/providers', { method: 'POST', body: JSON.stringify({ ref, kind, host, port: Number(port), username, credential_ref: credentialRef, tls_mode: tlsMode, auth_method: authMethod, mailbox, display_name: ref, sender_email: username, inbound_enabled: kind === 'imap' }) }), 'Provider account saved without a network connection')
  const selectTestAccount = (profile: ApiRecord) => { setTestRef(profile.ref); setTestSender(profile.sender_email || profile.username || ''); setTestAuthorization(''); setTestKey(newTestKey()); setGrantIssued(false) }
  const issueGrant = () => onRun(async () => { const result = await api<ApiRecord>(`/providers/${testRef}/grants`, { method: 'POST', body: JSON.stringify({ sender: testSender, recipient: testRecipient, purpose: testPurpose, expires_at: testExpiry }) }); setTestAuthorization(String(result.authorization_ref || '')); setTestKey(newTestKey()); setGrantIssued(true); return result }, 'Server-issued one-submission authorization prepared')
  const runTest = () => {
    if (!testConfirmed) return
    return onRun(() => api(`/providers/${testRef}/test-send`, { method: 'POST', body: JSON.stringify({ sender: testSender, recipient: testRecipient, message: testMessage, idempotency_key: testKey, authorization_ref: testAuthorization, purpose: testPurpose, expires_at: testExpiry }) }), 'Controlled test result recorded')
  }
  const configureInbound = () => onRun(() => api(`/providers/${inboundRef}/inbound`, { method: 'POST', body: JSON.stringify({ mailbox, max_fetch: Number(maxFetch), sync_enabled: syncEnabled, mutation_enabled: mutationEnabled }) }), 'Inbound configuration saved')
  return <div className="content"><div className="toolbar"><div><p className="eyebrow">PROVIDER ACCOUNTS</p><p className="muted">Configure named accounts from a protocol profile, then inspect separately proven configuration, credential, and connection evidence.</p></div><span className="status-chip">{profiles.length} accounts</span></div>
    <div className="split"><section className="panel"><div className="panel-head"><div><h3>Add account</h3><p className="muted">Saving validates local configuration only; it never contacts a provider.</p></div><span className="tag">local setup</span></div><label>Provider profile<select aria-label="Provider profile" value={preset} onChange={event => applyPreset(event.target.value)}>{capabilities.map(item => <option key={item.key} value={item.key}>{item.label}</option>)}</select></label><label>Account reference<input value={ref} onChange={event => setRef(event.target.value)} /></label><label>Protocol<select value={kind} onChange={event => changeKind(event.target.value)}>{(capability?.protocols || ['smtp', 'imap']).map((item: string) => <option key={item} value={item}>{item.toUpperCase()}</option>)}</select></label><label>Authentication<select aria-label="Authentication method" value={authMethod} onChange={event => setAuthMethod(event.target.value)}>{(capability?.auth_methods || ['password', 'oauth2']).map((item: string) => <option key={item} value={item}>{item === 'oauth2' ? 'OAuth 2.0 / XOAUTH2' : 'Password over TLS'}</option>)}</select></label><label>Host<input value={host} onChange={event => setHost(event.target.value)} /></label><label>Port<input type="number" value={port} onChange={event => setPort(event.target.value)} /></label><label>Username or sender identity<input value={username} onChange={event => setUsername(event.target.value)} /></label><label>Credential reference<input value={credentialRef} onChange={event => setCredentialRef(event.target.value)} /><small className="muted">Reference only. Secrets and OAuth tokens never enter the browser or SQLite.</small></label><label>TLS mode<select value={tlsMode} onChange={event => setTlsMode(event.target.value)}>{(capability?.tls_modes || ['implicit_tls', 'starttls']).filter((item: string) => kind !== 'imap' || item === 'implicit_tls').map((item: string) => <option key={item} value={item}>{item === 'starttls' ? 'STARTTLS' : 'Implicit TLS'}</option>)}</select></label>{kind === 'imap' && <label>Initial mailbox<input value={mailbox} onChange={event => setMailbox(event.target.value)} /></label>}{capability && <div className="preview-box"><strong>{capability.label} capability profile</strong><span>Scopes: {(capability.scopes || []).join(' · ') || 'No prescribed OAuth scope'}</span>{(capability.restrictions || []).map((restriction: string) => <small key={restriction}>{restriction}</small>)}</div>}<button className="primary full" disabled={!ref || !host || !username || !credentialRef} onClick={create}>Save account configuration</button></section><section className="panel table-panel"><div className="panel-head"><div><h3>Configured accounts</h3><p className="muted">Each status records evidence; none proves inbox delivery.</p></div></div>{profiles.length ? <table><thead><tr><th>Account</th><th>Protocol / auth</th><th>Endpoint</th><th>Evidence state</th><th>Actions</th></tr></thead><tbody>{profiles.map((profile: ApiRecord) => <tr key={profile.ref}><td><strong>{profile.display_name || profile.ref}</strong><small className="table-subline">{profile.ref} · credential reference only</small></td><td><span className="tag">{profile.kind} · {profile.auth_method}</span></td><td>{profile.host}:{profile.port}</td><td>{profile.status || 'not configured'}</td><td><div className="button-row"><button onClick={() => onRun(() => api(`/providers/${profile.ref}/validate`, { method: 'POST' }), 'Configuration validated without network contact')}>Validate config</button><button onClick={() => onRun(async () => setSelected(await api(`/providers/${profile.ref}/credentials`)), 'Credential reference readiness inspected')}>Check reference</button><button onClick={() => onRun(async () => setSelected(await api(`/providers/${profile.ref}/diagnostics`, { method: 'POST', body: JSON.stringify({ operation: 'connection' }) })), 'Loopback diagnostic recorded; external targets remain unverified')}>Run diagnostic</button><button onClick={() => { selectTestAccount(profile); setInboundRef(profile.ref) }}>Open operations</button></div></td></tr>)}</tbody></table> : <Empty text="No provider accounts yet. Choose a profile and add a local SMTP or IMAP account." />}{selected && <section className="preview-box" aria-live="polite"><strong>{selected.status || 'Provider evidence'}</strong><span>{selected.detail || selected.credential_ref || 'No secret value is displayed.'}</span><small>External access: {selected.external_access ? 'observed' : 'not observed'}</small></section>}</section></div>
    {profiles.length ? <div className="split"><section className="panel"><div className="panel-head"><div><h3>Controlled test message</h3><p className="muted">Prepare one synthetic message, then request a server-issued, expiring grant before any submission.</p></div><span className="status-chip amber-chip">No inbox guarantee</span></div><label>Account<select aria-label="Test account" value={testRef} onChange={event => setTestRef(event.target.value)}><option value="">Choose an account</option>{profiles.map((profile: ApiRecord) => <option key={profile.ref} value={profile.ref}>{profile.display_name || profile.ref}</option>)}</select></label><label>Sender<input value={testSender} onChange={event => { setTestSender(event.target.value); setGrantIssued(false) }} /></label><label>Owner-controlled recipient<input value={testRecipient} onChange={event => { setTestRecipient(event.target.value); setGrantIssued(false) }} /></label><label>Message preview<textarea value={testMessage} onChange={event => setTestMessage(event.target.value)} rows={5} /></label><details><summary>Advanced authorization and request identity</summary><p className="muted">Mailforge generates the idempotency identity. Authorization references are issued by the local server and cannot be invented in this form.</p><label>Application-generated idempotency key<input value={testKey} readOnly /></label><label>Authorization reference<input value={testAuthorization} readOnly placeholder="Issue a grant below" /></label><label>Purpose<input value={testPurpose} onChange={event => { setTestPurpose(event.target.value); setGrantIssued(false) }} /></label><label>Authorization expiry<input value={testExpiry} onChange={event => { setTestExpiry(event.target.value); setGrantIssued(false) }} /></label></details><label><input type="checkbox" checked={testConfirmed} onChange={event => setTestConfirmed(event.target.checked)} /> I confirm this exact sender, recipient, message, and one-submission scope.</label><div className="button-row"><button onClick={issueGrant} disabled={!testRef || !testSender || !testRecipient || !testPurpose || !testExpiry || !testConfirmed}>Prepare server authorization</button><button className="primary" disabled={!grantIssued || !testAuthorization || !testKey} onClick={runTest}>Submit one controlled test</button></div></section><section className="panel"><div className="panel-head"><div><h3>Inbound configuration</h3><p className="muted">Select a mailbox and bounded fetch limit; saving does not fetch mail or authorize acquisition.</p></div><span className="tag">read-only default</span></div><label>Account<select aria-label="Inbound account" value={inboundRef} onChange={event => setInboundRef(event.target.value)}><option value="">Choose an account</option>{profiles.map((profile: ApiRecord) => <option key={profile.ref} value={profile.ref}>{profile.display_name || profile.ref}</option>)}</select></label><label>Mailbox/folder<input value={mailbox} onChange={event => setMailbox(event.target.value)} /></label><label>Maximum messages<input type="number" min="1" value={maxFetch} onChange={event => setMaxFetch(event.target.value)} /></label><label><input type="checkbox" checked={syncEnabled} onChange={event => setSyncEnabled(event.target.checked)} /> Allow authorized synchronization</label><label><input type="checkbox" checked={mutationEnabled} onChange={event => setMutationEnabled(event.target.checked)} /> Allow authorized remote flags/move/copy</label><button className="primary full" disabled={!inboundRef || !mailbox || !maxFetch} onClick={configureInbound}>Save inbound settings</button><p className="muted">Permanent deletion and EXPUNGE are never available. Diagnostics remain separate from acquisition.</p></section></div> : <section className="panel"><h3>Next step</h3><p className="muted">Add and validate a provider account first. Controlled test and inbound setup appear here after an account exists, so empty setup does not look like an authorization request.</p></section>}
    <section className="panel"><div className="panel-head"><div><h3>Operational boundary</h3><p className="muted">Local protocol tests can prove fixture compatibility only. A real connection or test message requires a matching, expiring owner authorization.</p></div><span className="status-chip amber-chip">External qualification pending</span></div><p className="muted">SMTP provider acceptance is not inbox delivery. Ambiguous post-DATA outcomes remain unresolved and are never replayed automatically.</p></section></div>
}
function Activity({ data }: { data: ApiRecord }) { const items = data.items || []; return <div className="content"><div className="toolbar"><div><p className="eyebrow">OPERATIONAL LEDGER</p><p className="muted">Append-only events from the canonical SQLite authority.</p></div></div><section className="panel table-panel">{items.length ? <table><thead><tr><th>When</th><th>Aggregate</th><th>Event</th><th>Details</th></tr></thead><tbody>{items.map((item: ApiRecord) => <tr key={item.id}><td>{new Date(item.occurred_at).toLocaleString()}</td><td>{item.aggregate_type} · {item.aggregate_id.slice(0, 8)}</td><td><strong>{item.event_type}</strong></td><td><code>{item.payload?.name || '—'}</code></td></tr>)}</tbody></table> : <Empty text="No operational events yet." />}</section></div> }
function Empty({ text }: { text: string }) { return <div className="empty"><span>○</span><p>{text}</p></div> }
export default App
